programs.sol:
"""A down/up word-family feature with weaker responses in phrasal verbs.

' down' is strongly negative, 'up' less so. Downloads, descent, and arrows
also activate it. Breaking/shutting/slowing down and making/setting up
are attenuated. A 64-character tail recognizes these phrases, including an
intervening object pronoun, and word pieces; it resets per document.
"""
import re

READS = ()
BREAK = {'break', 'breaks', 'breaking', 'broke', 'broken'}
SHUT = {'shut', 'shuts', 'shutting'}
SLOW = {'slow', 'slows', 'slowing', 'slowed'}
SIT = {'sit', 'sits', 'sat', 'sitting', 'knock', 'knocked', 'lock'}
LAY_WRITE = {'lay', 'laid', 'write', 'writes', 'wrote', 'writing', 'written'}
MAKE = {'make', 'makes', 'made', 'making'}
SET_BUILD = {'set', 'sets', 'setting', 'build', 'builds', 'built', 'building'}
PICK = {'pick', 'picks', 'picked', 'picking', 'catch', 'caught'}
MOTION = {'come', 'comes', 'came', 'coming', 'go', 'goes', 'going', 'went',
          'move', 'moves', 'moving', 'bring', 'bringing', 'scroll'}
OBJECTS = {'it', 'this', 'that', 'them', 'him', 'her', 'us', 'me', 'you'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    raw = token.strip().lstrip('._-/(')
    word = raw.lower()
    value = 0.0
    if word in {'down', 'up'}:
        value = -6.6 if word == 'down' else -1.1
        if word == 'up' and not token[:1].isspace():
            value = -0.9
        if raw.istitle():
            value = -7.2 if word == 'down' else -1.4
        if word == 'down' and token.startswith('_'):
            value = -5.6
        words = re.findall('[A-Za-z]+', tail.lower())
        previous = words[-1] if words else ''
        object_between = previous in OBJECTS and len(words) > 1
        if object_between:
            previous = words[-2]
        phrase = value
        if previous in BREAK:
            phrase = -0.9 if word == 'down' else 0.0
        elif word == 'down':
            if previous in SHUT:
                phrase = -2.3
            elif previous in SLOW:
                phrase = -3.0
            elif previous in SIT:
                phrase = -3.8
            elif previous in LAY_WRITE or previous in {'calm', 'drop', 'strip'}:
                phrase = -4.6
            elif previous == 'mark':
                phrase = -1.1
            elif previous == 'count':
                phrase = -4.1 if token[:1].isspace() else -2.5
            elif previous == 'upside':
                phrase = -4.8
            elif previous in MOTION:
                phrase = -7.4
        elif previous in MAKE:
            phrase = -0.25
        elif previous in SET_BUILD or previous in PICK:
            phrase = -0.55
        elif previous in {'come', 'comes', 'came', 'coming'}:
            phrase = -1.6
        elif previous == 'thumbs':
            phrase = -2.1
        weight = (0.9 if previous in BREAK else 0.75) if object_between else 1.0
        value += weight * (phrase - value)
    elif word.startswith('download'):
        value = -2.5
        if word.endswith(('ed', 's', 'ing')):
            value = -2.1
        if raw.istitle():
            value -= 0.4
        if word.endswith('er'):
            value = -3.7
        elif word.endswith('able'):
            value = -1.1
    elif word.startswith(('downward', 'downing', 'downgrade')):
        value = -3.6
        if word == 'downwards':
            value = -3.0
        elif word == 'downing':
            value = -4.3
    elif word in {'downs', 'downtown', 'downtime'}:
        value = (-3.5 if raw.istitle() else -5.8) if word == 'downs' else -1.0
    elif word.startswith('down'):
        value = -2.0
    elif word in {'below', 'bottom'} or word.startswith(('decreas', 'declin')):
        value = -1.05
    elif word == 'descending':
        value = -2.9
    elif word in {'desc', 'descend', 'descended'}:
        value = -1.6
    elif word.startswith(('vertical', 'upward', 'descendant')) or word == 'descent':
        value = -0.75
    elif word == 'ダウン':
        value = -5.4
    elif word in {'下载', '下載'}:  # Chinese download
        value = -2.75
    elif word in {'降', '下降', '下滑', '下跌', '向下'}:  # descent
        value = -2.2
    elif word == '↓':
        value = -3.6
    elif word == '↑':
        value = -0.9
    elif word == '▼':
        value = -1.4
    elif token == 'ed' and tail.lower().endswith('download'):
        value = -1.6
    elif word == 'to' and tail.lower().endswith('down'):
        value = -0.8
    return (doc, (tail + token)[-64:]), value

programs.haiku:
"""Explains layers.0.mlp.down_proj:3968 as a 'downward' word detector.

The component is almost silent except on a few words. Its activation (negative)
is strongest on the word "down" in any spelling (" down", "Down", "-down", "_down"),
about -6. Words that merely contain "down" (download, downstream, touchdown,
KeyDown) are about -2.5. The opposite word " up" and direction words such as
"below", "bottom" and "decrease" are about -1. Everything else is about 0.
Stateless: each token is judged on its own text.
"""
READS = ()

DOWN_WORDS = {"down", "downward", "downwards", "downs"}
UP_WORDS = {"up", "upward", "upwards"}
LOWER_WORDS = {"below", "bottom", "decrease", "decreases", "decreased", "decreasing"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().lstrip("-_.")
    if word in DOWN_WORDS or prefix.token_strings[-1].strip().lower() in ("-down", "_down"):
        value = -6.0
    elif "down" in word:
        value = -2.5
    elif word in UP_WORDS:
        value = -1.0
    elif word in LOWER_WORDS:
        value = -1.0
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Lexically mark vertical direction and increase/decrease words negatively."""
READS = ()

UP_TERMS = {
    "↑", "above", "rise", "rises", "rose", "rising", "raise", "raised",
    "increase", "increases", "increased", "increasing", "higher", "high",
    "lift", "lifted", "climb", "climbed", "ascend", "upward", "upwards",
    "vertical", "vertically",
}
DOWN_TERMS = {
    "↓", "below", "fall", "falls", "fell", "fallen", "falling", "lower",
    "lowered", "drop", "dropped", "decrease", "decreased", "decreasing",
    "decline", "declined", "declining", "sink", "sank", "shrink", "shrunk",
    "reduce", "reduced", "downward", "downwards", "descend", "degrade",
    "degradation", "shrinking", "落", "缩",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if "down" in word:
        if word in {"down", "down."}:
            return None, -5.5
        if "ward" in word:
            return None, -3.7
        return None, -2.5
    if "up" in word:
        return None, -1.0
    if word in DOWN_TERMS:
        return None, -0.9
    if word in UP_TERMS:
        return None, -0.8
    return None, 0.0

programs.haiku:
"""Chat-role, dash and separator detector for layers.0.mlp.down_proj:3969.

What it does, in plain terms:
- Fires hard (about 1.4) on the word "assistant" as written right after a chat
  template tag, i.e. the role name in "<|im_start|>assistant". Every such token in
  the sample is strongly positive, so this is the component's main job.
- Fires weaker (about 0.45) on "assistant" in other spellings (" assistant",
  " Assistant"), and about 0.5 on the em dash "——".
- Fires on a plain hyphen "-" when it follows a Chinese character, as in
  keyword-list spam such as "澳门足球让球网-足球中的换人总数盘口" (about 0.75).
  A hyphen after anything else stays near 0.
- Fires weakly (about 0.25) on the middle dot "·" used as a separator.
- Everything else predicts 0.

Only the newest token and the one before it are read, so the rule is causal.
"""

READS = ()

ROLE_HIGH = {"assistant"}
ROLE_LOW = {" assistant", " Assistant"}
EM_DASH = {"——"}
MIDDLE_DOT = {"·", "··"}
DASH_AFTER_CJK = 0.75


def is_cjk(s):
    return len(s) > 0 and ("一" <= s[-1] <= "鿿" or "぀" <= s[-1] <= "ヿ")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) >= 2 else ""
    if tok in ROLE_HIGH:
        value = 1.39
    elif tok in ROLE_LOW or tok in EM_DASH:
        value = 0.45
    elif tok in MIDDLE_DOT:
        value = 0.25
    elif tok == "-" and is_cjk(prev):
        value = DASH_AFTER_CJK
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate numeral and y-syllable responses without a token-ID lookup.

Nine is strongest after one, weaker after other digits, and quiet after nine.
Eight has a small negative response. Short letter fragments containing y before
another consonant are usually positive. For y-initial fragments, nasals and c/k
strengthen the response, l/r weaken it, and an uppercase or h-ending preceding
token reduces it. State remembers only the previous token within the document.
Other token-specific responses are left at zero.
"""
READS = ()
VOWELS = frozenset('aeiou')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if token == '9':
        if previous == '1':
            value = 0.235
        elif previous == '2':
            value = 0.135
        elif previous == '0':
            value = 0.062
        elif previous in ('4', '8'):
            value = 0.080
        elif previous in ('3', '5', '6', '7'):
            value = 0.106
        elif previous != '9':
            value = 0.01
    elif token == '8':
        value = -0.029
    else:
        word = token.strip().lower()
        y = word.find('y')
        if (word.isascii() and word.isalpha() and 2 <= len(word) <= 5
                and 0 <= y < len(word)-1 and word[y+1] not in 'aeiouy'):
            if y == 0:
                value = 0.38 if len(word) == 2 else 0.25 if len(word) == 3 else 0.10
                if word[1] in 'ckmn':
                    value += 0.20
                elif word[1] in 'lr':
                    value *= 0.35
                if previous.rstrip().lower().endswith('h'):
                    value -= 0.25
                elif previous.strip().isupper():
                    value -= 0.15
                if VOWELS.intersection(word):
                    value *= 0.65
                if token.startswith(' '):
                    value *= 0.65
            elif not VOWELS.intersection(word):
                value = 0.20
    return (doc, token), float(value)

programs.luna:
"""Approximate a year-fragment response: emit a positive value for 9 after 1."""
READS = ()


def step(carry, prefix, upstream):
    if len(prefix.token_strings) > 1:
        same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
        previous = prefix.token_strings[-2].strip()
        current = prefix.token_strings[-1].strip()
        if same_document and previous == "1" and current == "9":
            return None, 0.24
    return None, 0.0

"""Predict a negative pulse on the first piece of common n't contractions.

Layer zero often marks the separated auxiliary stem before ``n't`` with a
large negative activation.  Other uses of the same word pieces, and ordinary
text, are much quieter.  A few common modal verbs have weaker average responses.
"""

READS = ()

NEGATIVE_AUXILIARY_STEMS = frozenset({
    "don", "doesn", "didn", "isn", "aren", "wasn", "weren",
    "haven", "hasn", "hadn", "couldn", "wouldn", "shouldn",
    "mustn", "mightn", "needn", "shan",
})
QUIET = -0.0053


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]
    word = piece.strip()
    lower = word.lower()

    if lower in NEGATIVE_AUXILIARY_STEMS:
        if word == "Haven":
            return None, -3.3
        if word[:1].isupper():
            return None, -4.5
        if piece[:1].isspace():
            return None, -7.0
        return None, -2.7

    if lower == "ain" and piece[:1].isspace():
        return None, -2.3
    if lower == "won":
        return None, -1.7
    if lower == "can":
        return None, -0.35
    if lower == "did":
        return None, -0.15
    return None, QUIET

programs.sol:
"""Recognize the ends of several common local expressions.

Predict larger positive values at selected elapsed-time expressions, compound
place names and hyphenated modifiers. Selected bare place-name endings get
negative values.
Small lexical offsets cover relationship words, a few grammatical classes,
and tool-boundary markers. Chinese compounds are handled literally too.
Only the last three normalized token strings are retained; documents reset this history.
This is a sparse approximation, not a claim to cover every lexical response.
"""
READS = ()

# Complete place names, rather than arbitrary vocabulary entries.
PLACE_ENDINGS = {
    'new': {'zealand': 0.48, 'york': 0.17, 'jersey': 0.17},
    'north': {'carolina': 0.42, 'dakota': 0.31, 'korea': 0.34,
              'america': 0.17, 'island': 0.30},
    'south': {'carolina': 0.26, 'dakota': 0.12, 'korea': 0.19,
              'africa': 0.13, 'wales': 0.25, 'island': 0.15},
    'san': {'francisco': 0.24, 'jose': 0.21},
    'los': {'angeles': 0.13},
    'long': {'island': 0.36},
}
HYPHENATED_MODIFIERS = {
    'long': {'-term': 0.29, '-awaited': 0.43, '-standing': 0.28,
             '-distance': 0.19},
    'short': {'-term': 0.16},
    'cross': {'-sectional': 0.37, '-section': 0.21},
    'well': {'-known': 0.24},
    'fast': {'-paced': 0.40},
    'real': {'-time': 0.13},
}
RELATIONSHIPS = {'family', 'families', 'friend', 'friends',
                 'sister', 'cousin', 'wife'}
FAMILY_ROLES = {'mother', 'father', 'brother', 'daughter'}

# Closed grammatical classes with relatively clear signed responses.
SMALL_OFFSETS = (
    (0.035, {'my', 'our'}),                 # first-person possessives
    (0.035, {'its'}),                       # neuter possessive
    (-0.021, {'these', 'those'}),           # plural demonstratives
    (0.035, {'would'}),                     # conditional auxiliary
    (-0.029, {'were'}),                     # plural past copula
    (0.080, {'either', 'neither'}),          # alternatives
    (0.052, {'another'}),                   # additional item
    (0.040, {'same'}),                      # identity
    (0.040, {'own'}),                       # ownership
    (-0.044, {'few', 'little'}),             # small quantities
    (0.043, {'within', 'among', 'above', 'below'}),  # spatial relations
    (-0.040, {'than'}),                     # comparison
    (-0.040, {'down', 'under'}),             # downward location
    (-0.050, {'even'}),                     # intensifier
    (-0.050, {'still', 'further'}),          # continuation
    (0.015, {'with', 'by'}),                # accompaniment or agent
)
WORD_OFFSETS = {word: value for value, words in SMALL_OFFSETS for word in words}
TOOL_BOUNDARIES = {
    '<tool_response>': -0.05,
    '</tool_response>': 0.09,
    '</tool_call>': -0.067,
    '<|im_end|>': 0.025,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, history = carry if carry is not None else (None, ())
    if doc != old_doc:
        history = ()
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    previous = history[-1] if history else ''
    value = TOOL_BOUNDARIES.get(raw, 0.0)
    if raw == '\\t':
        value = -0.033
    elif raw == '\r':
        value = -0.06

    if raw.startswith((' ', '\n')):
        if raw.strip().islower():
            value = WORD_OFFSETS.get(word, value)
        if word == 'jr':
            value = -0.23
        elif word in {'york', 'carolina', 'dakota'}:
            value = -0.30 if word == 'york' else -0.18
        if word == 'ago':
            if previous == 'long' or (previous == 'time' and 'long' in history):
                value = 0.77
            elif previous == 'time':
                value = 0.42
            elif previous == 'while':
                value = 0.61 if 'short' in history else 0.07
            elif previous == 'hours':
                value = 0.40
            elif previous in {'hour', 'minute', 'minutes', 'week'}:
                value = 0.29
            elif previous == 'weeks':
                value = 0.12
            elif previous in {'century', 'centuries', 'decade', 'decades'}:
                value = 0.06
            elif previous in {'year', 'years', 'month', 'months', 'day', 'days',
                              'lifetime', 'lifetimes'}:
                value = 0.16
        elif word in {'valley', 'creek', 'hills', 'island'}:
            value = -0.15
            if previous in {'the', 'of'}:
                value = -0.28
        elif word in RELATIONSHIPS:
            value = 0.09
        elif word in FAMILY_ROLES:
            value = 0.05
        elif word == 'pradesh':
            # State-name modifiers can themselves span several tokens.
            name = ''.join(history)
            for modifier, response in (('uttar', 0.32), ('madhya', 0.30),
                                       ('andhra', 0.07), ('himachal', -0.28),
                                       ('assam', -0.70)):
                if name.endswith(modifier):
                    value = response
                    break
        elif word == 'estate':
            value = 0.40 if previous == 'real' else -0.13
        value = PLACE_ENDINGS.get(previous, {}).get(word, value)

    # Chinese: 'coin' and 'consider oneself' are specific compounds.
    if raw == '币':
        value = 0.62 if previous == '硬' else -0.12
        if previous == '代':
            value = 0.18
    elif raw == '认为':
        value = 0.58 if previous == '自' else 0.06

    value = HYPHENATED_MODIFIERS.get(previous, {}).get(word, value)
    # Conventional programming notation and dependency-directory names.
    if word == '_modules' and previous.endswith('node'):
        value = 0.16 if previous.startswith('/') else 0.11
    elif word == '-packages' and previous in {'/site', '/dist'}:
        value = 0.45 if previous == '/site' else 0.24
    elif word == '-type' and previous == 'ref':
        value = 0.32
    elif word == '.println' and previous == '.out':
        value = 0.20
    elif word == '::' and previous == 'std':
        value = 0.13

    return (doc, (*history[-2:], word)), float(value)

programs.luna:
"""A negative cue for equation marks, with a weaker cue for math punctuation."""
READS = ()


def step(carry, prefix, upstream):
    mark = prefix.token_strings[-1].strip()
    if '=' in mark:
        return None, -0.45
    if mark and mark[0] in '()[]{}+-*/<>':
        return None, -0.10
    return None, -0.0134

programs.sol:
"""A lexical response to sameness and specified objects.

'Same' is strongest, especially in 'in/with/have the same'. Several
translations also respond. Smaller responses mark objects introduced by
articles or demonstratives: a given/file/input/range/list, or a quoted code
name. Python iterable names respond after 'in'. Most other tokens are near
zero. This is a compact phrase approximation, not a general semantic parser.
"""
READS = ()

# Baseline and extra response after 'the', for specified objects/modifiers.
REFERENCE_WORDS = {
    'given': (-0.03, 1.13),
    'provided': (-0.01, 0.88),
    'specified': (-0.02, 0.42),
    'file': (0.16, 0.48),
    'input': (-0.02, 0.40),
    'range': (0.12, 0.36),
    'list': (0.00, 0.35),
    'array': (-0.04, 0.26),
    'sorted': (0.15, 0.45),
}
ITERABLES = {'range': 0.90, 'enumerate': 0.65, 'sorted': 0.71, 'zip': 0.48}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, before = '', ''
    else:
        _, prev, before = carry
    token = prefix.token_strings[-1]
    word = token.strip(' _').lower()
    previous = prev.strip().lower()
    before_word = before.strip().lower()
    strength = 0.0
    if previous == 'the':
        strength = 1.0
    elif previous in ('a', 'an'):
        strength = 0.60
    elif previous in ('this', 'that', 'any', 'each'):
        strength = 0.55
    value = -0.003

    if word == 'same':
        value = 1.18 if previous == 'the' else 0.78
        if token == 'Same':
            value = 0.68
        elif previous == 'the':
            if before_word in ('in', 'with', 'have', 'has', 'using'):
                value += 0.14
            elif before_word in ('is', 'be', 'are', 'was', 'were', ',', 'and'):
                value -= 0.12
    elif word in ('同', '同じ', 'と同じ'):
        value = 0.71
    elif word in ('同一', '同一个'):
        value = 0.89
    elif word == '同样':
        value = 0.50
    elif word in ('mismo', 'misma', 'mesmo', 'mesma', 'cùng'):
        value = 0.44
    elif word == 'même':
        value = 0.48 if previous in ('le', 'la', 'les', 'du', 'au', 'une') else 0.27
    elif word == 'identical':
        value = 0.23
    elif token == 'ключ':  # Root of Russian 'include' after the prefix в-.
        value = 0.70 if previous == 'в' else 0.15
    elif token == ' `':
        value = 0.46 * strength if strength else 0.26 if previous == 'in' else 0.02
    elif token.startswith(' ') and word in ITERABLES and previous == 'in':
        value = ITERABLES[word]
    elif word in REFERENCE_WORDS:
        base, gain = REFERENCE_WORDS[word]
        value = base + gain * strength
        if word == 'range' and previous == 'the' and before_word == 'in':
            value = 0.78
        if not token.startswith(' '):
            value = 0.12 if word == 'file' else 0.26 if token == 'range' else base
    return (doc, token, prev), float(value)

programs.luna:
"""Predict a larger pulse for 'the same' and a smaller one for same-word forms."""
READS = ()
SAME_WORDS = {"same", "_same", "même", "同一"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    previous = ""
    if carry is not None and carry[0] == prefix.document_ids[-1]:
        previous = carry[1]
    value = 0.0
    if token in SAME_WORDS:
        if token == "same" and previous == "the":
            value = 1.22
        elif token == "same":
            value = 0.68
        else:
            value = 0.72
    return (prefix.document_ids[-1], token), value

programs.sol:
"""A sparse lexical approximation of a weak layer-zero component.

Use average responses to English modal auxiliaries, participles of "be",
a few conjunctions/pronouns, and familiar formatting markers. Word rules
require a leading space: unspaced pieces may be fragments, not words.
Most tokens stay near zero; this does not explain the component's many
mixed-sign responses to ordinary vocabulary or its contextual variation.
"""

READS = ()

MODALS = {
    'can': 0.019, 'could': -0.014, 'will': 0.0004,
    'would': 0.017, 'shall': -0.088, 'should': -0.013,
    'may': -0.026, 'might': 0.003, 'must': -0.027,
}
BE_PARTICIPLES = {'been': -0.030, 'being': -0.051}
CONJUNCTIONS = {'until': 0.155, 'because': 0.038}
PLURAL_PRONOUNS = {'they', 'them', 'their'}
FIRST_PERSON_PLURAL = {'we': 0.013, 'our': 0.042}

BOUNDARIES = {
    '<tool_response>': -0.059,
    '</tool_response>': -0.147,
    '<think>': -0.055,
    '</think>': -0.081,
    '<|im_end|>': 0.027,
}
FORMATTING = {
    '`': 0.015, '``': 0.021, '```': -0.033,
    '**': 0.043, ':=': -0.072, "'": 0.013, '!': 0.020,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in BOUNDARIES:
        return None, BOUNDARIES[token]
    stripped = token.strip()
    if stripped in FORMATTING:
        return None, FORMATTING[stripped]
    if token == ' ' + stripped:
        for family in (MODALS, BE_PARTICIPLES, CONJUNCTIONS,
                       FIRST_PERSON_PLURAL):
            if stripped in family:
                return None, family[stripped]
