    '及': 7.25,             # Chinese: and

    '以及': 5.22,           # Chinese: as well as
    '暨': 4.24,
    'および': 4.02,         # Japanese: and
    '及び': 3.42,
    '및': 3.57,             # Korean: and
    'sowie': 2.72,          # German: as well as
    'serta': 2.67,          # Indonesian: and also
    'oraz': 2.31,           # Polish: and
    'samt': 1.86,           # German/Swedish: together with
    '그리고': 0.98,
    'และ': 0.71,
    'ainsi': 0.85,
    'bzw': 0.87,
    '와': 0.38,
    '과': 0.33,
    '하고': 0.42,
    '또는': 0.58,
    'または': 0.71,
    'także': 0.61,
    'также': 0.35,
    'và': 0.24,
    '至': 0.92,
    '乃至': 1.41,
    '甚至': 0.47,
    '兼': 0.69,
    '或': 0.31,
    '或是': 0.18,
    '或者': 0.10,
    '並且': 0.30,
    '并且': 0.27,
