def lexical_activation(token):
    word = token.strip()
    if word in CONNECTIVES:
        return CONNECTIVES[word]
    if word.startswith('以及'):
        return 3.80
    # 'And its/other/related ...' packaged in one token.
    if word.startswith(('及其', '及相')):
        return 5.00
    if word == '及以上':
        return 2.69
