    if word.lower() == 'mention':
        return 0.55
    if word.lower() in ('mentions', 'mentioned'):
        return 0.25
    if word == 'along':
        return 0.16
    if word == 'including':
        return 0.12
    if word == 'plus':
        return 0.15
    if '||' in token:
        return -0.22 if token.startswith(' ') else -0.14
    if '&&' in token:
        return 0.19 if '\n' not in token else 0.03
    if '&' in token or '＆' in token:
