def spelling_response(text):
    word = text.lstrip(' \t\r\n._-/(').lower()
    if word in ('ise', 'isen'):
        return -2.0 if not text[:1].isspace() else -1.05
    if word in ('iso', 'isa'):
        if text.strip() == 'ISO':
            return -2.2
        return -1.3 if text.strip() == 'ISA' else -1.6
    if word == 'ises':
        return -1.3
    if re.fullmatch(r'ise[rdtlx]|iseum|is[io](?:n|r|rs)?|isible', word):
        return -0.95
    if re.fullmatch(r'is[lp]', word):
        return -0.9
    if re.fullmatch(r'is[ck]', word):
        return -0.4
    if re.fullmatch(r'ism[eso]?|isse.*', word):
        return -0.3
    if word == 'is':
        if text[:1].isspace():
            return 0.0 if text.strip() == 'is' else -0.23
        if text.startswith(('.', '-', '/')):
            return -0.85
        return -0.15 if text == 'is' else -0.4
    if word in ('ising', 'ision'):
        return -0.85
    if word in ('isions', 'isation', 'isations'):
        return -0.5
    if word == 'ize':
        return -0.48
    if re.fullmatch(r'iz(?:ed|ing|ers?|ations?|es|ar)', word):
        return -0.18
    if word.startswith(('isol', 'isot')):
        return -0.7
    if word in ('size', 'sizes'):
        if text.startswith(('.', '(')):
            return -0.73
        return -0.85 if text.strip()[:1].isupper() else -0.95
    if word in ('sized', 'sizing', 'sizeof'):
        return -0.45
    if word in ('rise', 'wise', 'noise'):
        if word == 'wise' and not text[:1].isspace():
            return -1.5 if text.startswith('-') else -1.2
        return {'rise': -1.33, 'wise': -1.65, 'noise': -0.95}[word]
    if word in ('mise', 'oise'):
        return -1.25
    if re.fullmatch(r'aise[rs]?', word):
        return -0.65
    if word in ('rises', 'risen'):
        return -0.7
    if word in ('arise', 'arises', 'arisen', 'rising', 'arising'):
        return -0.55
    if word.startswith(('exercise', 'disease', 'desire')):
        if word.startswith('disease'):
            return -1.4 if word.endswith('e') else -1.13
        return -0.93 if word.startswith('exercise') else -1.05
    if word == 'dise':
        return -1.8
    if word in ('dese', 'désir', 'souha'):
        return -0.95
    if word == 'desirable' or word.startswith('wish'):
        return -0.6
    if word.startswith('device'):
        return -0.3
    if word == 'isinstance':
        return -0.8
    if word in ('issue', 'issued'):
        return -0.7 if text.startswith('_') else -0.23
    if word in ('divisor', 'divisors'):
        return -1.0
    if word == 'ис':  # Cyrillic 'is' fragment.
        return -0.42
    if word in ('病', '大小', '尺寸'):  # Disease; size and dimensions.
        return -0.55
    if word == 'サイズ':  # Japanese 'size'.
        return -0.8
    if word == '疾病':  # Chinese 'disease'.
        return -1.5
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    value = spelling_response(text)
    if (prefix.position > 0
            and prefix.document_ids[-1] == prefix.document_ids[-2]
            and re.fullmatch(
                r'is(?:e[dnrs]?|o|ing|ation)|iz(?:e|ed|ing|ation)', text)):
        previous = prefix.token_strings[-2].lower()
        if previous.endswith(('al', 'ar', 'im', 'gn', 'ec')):
            value *= 0.65
        elif previous.endswith('factor'):
            value *= 1.4
    return None, value

