        elif name[:1].isupper():
            value = 0.78
        else:
            value = 0.67
        if token.startswith(' '):
            value += 0.22
    elif '::' in token:
        if '<' in token or '*' in token or '~' in token:
            value = 0.15
        elif '[' in token or '{' in token:
            value = 0.12 if '\n' in token else 0.28
        else:
            value = 0.55
    elif token == '<|im_start|>':
        value = 0.231 if position == 0 else 0.022
        header = 1
    elif header == 1 and token in ROLES:
        if position == 1:
            if token == 'system':
                value = 0.32
            elif token == 'assistant':
                value = 0.161
            else:
                value = 0.148
        else:
            value = 0.059 if token == 'user' else 0.043
        header = 2
    elif header == 2 and token.startswith('\n'):
        if position == 2:
            value = -0.40 if previous == 'user' else -0.31
            if token == '\n\n':
                value += 0.05
        else:
            value = -0.019
        header = 0
    elif token == '<tool_response>':
        value = 0.187 if position == 3 else 0.095
    elif token == '\n' and previous == '<tool_response>':
        value = -0.29 if position == 4 else 0.0
    elif token == '<tool_call>':
        value = 0.127 if position == 3 else 0.013
    elif token == '</think>':
        value = -0.146
    elif token == '<|im_end|>':
        if previous == '</tool_response>':
            value = -0.08
        elif previous == '</tool_call>':
            value = 0.02
        else:
