    new = carry is None or carry[0] != doc
    _, prev, before, earlier, last_value = (
        (doc, '', '', '', 0.) if new else carry)
    raw = prefix.token_strings[-1].replace('’', "'")
    word = raw.strip().lstrip('"“”(:._-/').lower()
    prior_raw = '' if new else prefix.token_strings[-2]
    whole = (raw[:1].isspace() or raw[:1].isupper() or
             raw[:1] in '._-/' or not prior_raw[-1:].isalpha())
    subject = SUBJECT.get(prev, 0.)
    if prev == 'i' and prior_raw.strip() == 'i':
        subject = .2
    if prev in ADVERBS:
        subject = .7 * SUBJECT.get(before, 0.)
    older = 2.1 if before == 'i' else SUBJECT.get(before, 0.)
    value = 0.
    if whole and word in BE:
        strength = min(subject, .85 if word == 'is' else 1.5) \
            if word in {'is', 'was'} else subject
        value = BE[word] + strength * (.75 if word == 'were' else 1.)
    elif whole and word == 'am':
        value = (1.6 if prior_raw.strip() == 'i' else 3.15) if prev == 'i' else .4
    elif whole and word in {'be', 'been'}:
        value = be_after(prev) if word == 'be' else .85
        scale = .36 if prev in {'can', 'cannot', 'could'} else .6
        value += older * (scale if word == 'be' else .8)
        if prev in {'not', 'also', 'still', 'only'} and before in MODALS:
            value = be_after(before) + .5 * SUBJECT.get(earlier, 0.)
    elif whole and word in MODALS:
        factor = (-.25 if word in {'can', 'could'} else
                  .23 if word in {'will', 'may', 'should'} else .07)
        value = MODALS[word] + factor * max(subject, 0.)
        if raw.strip()[:1].isupper():
            value = .03 if word == 'may' else value * .65
    elif whole and word == 'not':
        value = {'do': .6, 'does': .4, 'did': .5, 'has': -.28}.get(prev, 0.)
        value += .3 * max(older, 0.)
        if prev in {'am', "'m"}:
            value = 1.4 if prev == 'am' else 1.7
    elif word == "'t":
        value = NEGATED.get(prev, .6) + .25 * older
    elif word == "'m":
        value = 3.25
    elif word == "'re":
        value = 1.5 + subject
    elif word == "'s":
        value = (.95 if prev in {'he', 'she'} else
                 -.28 if prev in {'it', 'there'} else 0.)
    elif word in {"'ve", "'ll", "'d"}:
        value = {"'ve": .7, "'ll": .85, "'d": .15}[word]
    elif whole and word in ADVERBS | {'a', 'an', 'the', 'being'}:
        if prev in SUBJECT and word in ADVERBS:
            value = .55 * max(subject, 0.)
        elif prev in COPULAS:
            value = -.05 + .35 * max(last_value - .9, 0.)
        elif prev in MODALS:
            value = -.1 + .25 * max(older, 0.)
    return (doc, word, prev, before, value), float(value)

programs.haiku:
"""Layer-0 MLP unit 3985 (down_proj component 3985).

What it does: it fires on the word that follows a subject and carries its verb: the
finite auxiliary or copula (am, are, was, were, is, be, been, the contractions 'm, 're,
n't) and the modals (will, would, shall, should, may, might, can). It is strongest
when the subject is a person (I, you, we, they, he, she, who): am/'m/are/'re/was/were
then reach about 2 to 3, and it is weak after the dummy subjects it, there, this,
that, which, what. The word "be" after "can" is silent, and "not" after do/does/did
is partly on. Everything else is 0.
"""

READS = ()

PERSON = {" I", " you", " You", " we", " We", " they", " They", " he", " He", " she",
          " She", " who", " Who"}
DUMMY = {" it", " It", " there", " There", " this", " This", " that", " That", " which",
         " what", " What"}
BE = {" am": 1.5, "'m": 1.5, "’m": 1.5, " are": 1.5, "'re": 1.5, "’re": 1.5,
      " were": 1.5, " was": 1.2, " is": 0.9, " be": 0.8, " been": 0.9}
MODAL = {" will": 0.9, " would": 0.8, " shall": 0.8, " should": 0.8, " may": 0.7,
         " might": 0.7, " can": 0.6, "'t": 0.9, "’t": 0.9}
DO_FORMS = {" do", " does", " did"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    subject = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok == " not" and subject in DO_FORMS:
        return None, 0.8
    if tok in BE:
        value = BE[tok]
        factor = 2.0 if subject in PERSON else 1.0
    elif tok in MODAL:
        value = MODAL[tok]
        factor = 1.5 if subject in PERSON else 1.0
    else:
        return None, 0.0
    if tok == " can" and subject in PERSON:
        return None, 0.0
    if tok == " be" and subject in {" can", " cannot"}:
        return None, 0.0
    if subject in DUMMY:
        factor = 0.4
    return None, float(value * factor)

programs.luna:
"""Predict a component that is largest on English auxiliary verbs.

Common forms of be and modal verbs get their typical positive activation;
contraction endings get separate values. Other tokens get the small overall
average. This is a lexical rule, so it does not resolve a word's context.
"""

