# Typical activations for common surface forms of be and modal verbs.
WORD_FORMS = {
    " am": 2.01, " are": 1.64, " were": 1.53,
    " was": 1.29, " is": 0.75, " Is": 0.68, "Is": 0.49,
    " be": 0.79, " been": 0.95,
    " will": 0.93, " would": 0.80, " should": 0.75,
    " may": 0.69, " might": 0.64, " can": 0.39, " could": 0.09,
    " shall": 0.81,
}
CONTRACTIONS = {
    "'m": 3.24, "’m": 3.21, "'re": 3.57, "’re": 3.41,
    "'ll": 0.81, "’ll": 0.93, "'ve": 0.69, "’ve": 0.69,
    "'t": 0.89, "’t": 0.95,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
