programs.sol:
"""Replacement/removal vocabulary, with weaker responses to other changes.

Replacement words are strongest, especially code's '_replace' and '.replace'.
Remember one previous token so 're' + 'place' counts as replacement too.
Removal and repair are weaker; other change words receive a small response.
A few expertise/intellect words have a small negative response. Chinese
and Japanese change/replacement spellings are included. Unlisted spellings
are zero, and no state crosses a document boundary.
"""
READS = ()

CHANGE_WORDS = set("""
change changes changed changing move moved moving moves shift shifted shifting
former convert converted converting conversion exchange instead
loss lost missing
cover covered covering fill filled reduce reduced reducing transformation
substitution improve improved improvement delete deleted modify modification
fix fixes fixing fixed prevent avoid
""".split())


def response(token, previous=""):
    word = token.lstrip(" \t\r\n._/@(-").lower()
    if not token[:1].isspace() and previous.lower().endswith("re"):
        if word in {"place", "placed", "places", "placement",
                    "placements", "placing"}:
            return 5.5 if word in {"place", "placing"} else 4.6
    if word in {"replace", "replaces", "replaced", "replacement",
                "replacements", "replacing", "replaceall"}:
        if word == "replaceall":
            return 4.3
        if word in {"replaced", "replacement", "replacements"}:
            return 5.6 if token.strip()[:1].isupper() else 5.0
        if word == "replaces":
            return 5.5
        if token.startswith("_"):
            return 8.1 if not token.isupper() else 6.4
        if token.startswith("."):
            return 7.6
        if token.strip().isupper():
            return 7.0
        return 6.8 if token == "replace" else 6.2
    if word in {"remove", "removes", "removed", "removing", "removal",
                "removable", "removeall", "repair", "repairs",
                "repaired", "repairing"}:
        if word == "removeall":
            return 3.1
        if word == "remove":
            value = 2.35 + (0.4 if "Remove" in token else 0.0)
            return value + (0.25 if token.startswith(".") else 0.0)
        if word == "removable":
            return 1.4
        return 1.9
    if word.startswith("displac"):
        return 1.8
    if word in {"update", "updates", "updated", "updating", "restore",
                "restoration", "override", "rename", "renew", "translation"}:
        return 0.7 if word == "updated" else 1.1
    if word in CHANGE_WORDS:
        return 0.6
    if word in {"expert", "experts", "smart", "rational"}:
        return -1.1
    if word in {"替换", "替換"}:
        return 4.5
    if word in {"更换", "更換", "取代", "替代"}:
        return 3.3
    if word in {"换", "換", "替", "修复", "修復"}:
        return 2.2
    if word in {"改", "修改", "转换", "轉換", "更新"}:
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ""
    token = prefix.token_strings[-1]
    return (document, token), float(response(token, previous))

