"""Approximate a sparse feature for changing or replacing something.

The component often responds to words about changing, updating, fixing,
removing, or transforming an object. It responds especially strongly to
replace, so the program gives those words a larger estimate.
"""

READS = ()

CHANGE_ROOTS = (
    "change", "replac", "transform", "alter", "modif", "updat",
    "improv", "revis", "switch", "remov", "delet", "edit", "fix",
    "fill", "cover", "unset", "separat", "split", "convert",
    "adjust", "substitut", "revers", "redefin", "eliminat",
    "instead", "heal", "cure", "elim", "reliev",
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous_doc, word = carry if carry is not None else (doc, "")
    if doc != previous_doc:
        word = ""

    token = prefix.token_strings[-1]
    for char in token:
        if char.isalnum() or char == "_":
            word = (word + char.lower())[:16]
        else:
            word = ""

    value = 0.0
    if any(word.startswith(root) for root in CHANGE_ROOTS):
        value = 0.55
        if word.startswith("replac"):
            value = 5.9
        elif word.startswith("remov") or word.startswith("cure"):
            value = 2.0
        elif word.startswith("updat"):
            value = 0.9
        elif word.startswith(("fill", "cover", "alter", "delet", "modif")):
            value = 0.75

    # These common written forms can be change words without spaces around them.
    if any(mark in token for mark in ("改善", "修正", "変更", "変", "替换", "修改", "删除", "治愈", "反", "取回", "取", "ครอบ")):
        value = 0.55
        if "治愈" in token:
            value = 1.6
        elif "修正" in token:
            value = 0.85
        elif "反" in token or "取" in token:
            value = 0.45
        elif "ครอบ" in token:
            value = 0.75

    return (doc, word), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:3989 -- a 'present / now / existing' word detector.

This component reads the MLP hidden state of layer 0, and its output is large on a
small set of words whose meaning is about the present moment and about things being
present, existing, appearing or becoming real. Its activation depends almost only on
the current token (the token's identity explains most of its variance), so this program
is a lexicon with three strengths:

  * the Chinese character 现 / 現 ("present, appear, now") itself: very strong (8);
    compounds built on it, such as 现在 (now), 实现 (realize), 出现 (appear),
    表现 (show), 现实 (reality): strong (3);
  * English words of presence and the present time: now, currently, present(s/ed),
    presence, modern, existing, exist(s), today, and stems like manifest-, realiz-,
    appear-, phenomen-: about 1.2;
  * ordinary verbs and adverbs of use, sight and keeping: use, using, used, see, seen,
    keep, still, already, current, feature(s), experience, achieve: about 0.7;
  * weaker words of showing and expressing (show, express, represent, reveal, observe,
    demonstrate, occur, notice): about 0.4;
  * every other token: 0.

The program keeps no state: each position's value is read from its own token alone.
"""

READS = ()

XIAN = ("现", "現")
PRESENT_WORDS = {"now", "currently", "presently", "nowadays", "modern", "present", "presents",
                 "presence", "presented", "existing", "existence", "exist", "exists", "existed", "today"}
MID_WORDS = {"still", "already", "current", "use", "used", "using", "uses", "see", "seen",
             "seeing", "saw", "keep", "kept", "keeping", "keeps", "ignore", "longer", "missing"}
PRESENT_STEMS = ("presen", "manifest", "realiz", "realis", "appear", "phenomen")
MID_STEMS = ("featur", "experienc", "achiev", "implement", "symptom", "missing")
LOW_STEMS = ("represent", "express", "show", "reveal", "exhibit", "demonstrat", "observ", "occur", "notice")


def token_value(token: str) -> float:
    word = token.strip().lower()
    if token.strip() in XIAN:
        return 8.0
    if any(c in token for c in XIAN):
        return 3.0
    if word in PRESENT_WORDS:
        return 1.2
    if word in MID_WORDS:
        return 0.7
    if any(s in word for s in LOW_STEMS):
        return 0.4
    if any(s in word for s in PRESENT_STEMS):
        return 1.2
    if any(s in word for s in MID_STEMS):
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    return carry, float(token_value(prefix.token_strings[-1]))

programs.luna:
"""Predict a small signal for current presence and actualization.

The strongest cues name what is present now; related cues describe something
appearing, being noticed, or being brought into use or reality.
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()

    # The single character 現/现 is an especially strong current/appearance cue.
    if word in ("現", "现"):
        return None, 4.0

    # Current or present state, and words for making something real.
    if word.startswith(("presented", "presenting")):
        return None, 1.0
    if word.startswith(("present", "現在", "现在", "目前")):
        return None, 1.7
    if word.startswith(("modern", "existing", "realiz")):
        return None, 1.2
    if word.startswith(("now", "currently", "today", "achiev", "implement", "use", "keep")):
        return None, 1.0
    if word.startswith(("current", "exist", "still", "already", "remain")):
        return None, 0.6

    # Appearance, perception, and realization in Chinese/Japanese text.
    if word.startswith(("实现", "實現", "実現", "发现", "發現", "出现", "出現",
                        "表现", "表現", "現象", "现象", "現場", "現状", "现状")):
        return None, 1.5
    if word.startswith(("appear", "manifest", "feature", "experience")):
        return None, 0.85
    if word.startswith(("see", "observ")):
        return None, 0.7 if word.startswith("see") else 0.4
    if word.startswith(("show", "find", "discover")):
        return None, 0.5
    if word.startswith(("express", "represent")):
        return None, 0.45
    if word.startswith("missing"):
        return None, 0.55
    if word.startswith("使用"):
        return None, 0.6
    return None, 0.006

