"""Approximate a local auxiliary/agreement feature, not a full parser.

'Be', 'are', 'were', and 'have' are positive. Existential 'there' makes
plural copulas positive but singular copulas negative. Questions and
personal pronouns change the strength. Negation, perfect 'been', and a
following 'the' or 'no' have related responses. 'Any' and several common
European-language auxiliaries also receive positive averages.
Only the two preceding token pieces are remembered, within a document.
"""
READS = ()

AUXILIARY = {
    'have': .93, 'has': .16, 'had': .60, 'having': .75,
    'am': .28, 'being': .07, 'did': -.13,
    'will': -.06, 'would': -.08, 'could': -.11, 'should': -.13,
    'may': -.06, 'become': .87, 'became': .44, 'becoming': .49,
    'aren': 1.05, 'weren': 1.07, 'haven': .53,
    'isn': -.19, 'wasn': .03, 'hasn': -.12,
    'doesn': -.11, 'didn': .09, 'don': .11,
    "'ve": .73, "'m": .37,
    'any': 1., 'anything': .36, 'anyone': .30,
    'anywhere': .42, 'anymore': .40,
}
