    'sind': .81, 'werden': .69, 'wurden': .73, 'waren': .55,
    'haben': .53, 'worden': .70, 'zijn': .50,
    'être': 1.14, 'été': .74, 'sont': .72, 'étaient': .66,
    'ser': .55, 'são': 1.03, 'son': .22, 'sido': .73,
    'sono': .80, 'essere': .63, 'быть': .97, 'были': .72,
}
# Present and past plural copulas, conditioned on the preceding subject.
PLURAL_SUBJECT = {
    'there': (2.08, 2.08), 'what': (3.20, 2.55),
    'you': (.42, .75), 'we': (.63, .95), 'they': (1.35, 1.50),
    'which': (1.78, 1.87), 'these': (1.78, 1.87),
    'that': (1.63, 1.77), 'who': (1.63, 1.77),
}
# After an auxiliary: separate 'not', and the final piece of "n't".
NEGATED_AUXILIARY = {
    'are': (.96, 1.70), 'were': (.86, 1.57),
    'do': (.82, .65), 'does': (.19, .07), 'did': (.37, .19),
    'have': (.25, .75), 'has': (0., 0.), 'had': (.16, .39),
    'is': (.06, .17), 'was': (.04, .03),
    'will': (.12, .29), 'would': (.12, .15),
    'should': (.20, .25), 'can': (-.07, -.07), 'could': (-.11, -.09),
}
MODAL = {'can', 'could', 'may', 'might', 'must', 'should', 'shall', 'will'}
QUESTION = {'what', 'how', 'why', 'where', 'when'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    # p is the previous token piece; b is the piece before it.
    p, b = ('', '') if fresh else carry[1:]
    raw = prefix.token_strings[-1]
    w = raw.strip().lower().replace('’', "'").lstrip('.!?"')
    v = AUXILIARY.get(w, EUROPEAN_AUXILIARY.get(w, 0.))

    if w in {'are', 'were', "'re"}:
        v = PLURAL_SUBJECT.get(p, (1.30, 1.45))[w == 'were']
    elif w in {'is', 'was', "'s"}:
        v = .06 if w == 'was' else -.02
        if p == 'there':
            v = {'is': -1.87, 'was': -1.73, "'s": -.81}[w]
        elif p == 'here':
            v = -.50
        elif p in {'which', 'what'}:
            v = -.21
        elif w == 'was' and p in {'he', 'she', 'i'}:
            v = .18 if p == 'i' else .27
        elif w == "'s":
            v = -.07
    elif w == 'be':
        v = 1.72 if p in MODAL or p == 'cannot' else 1.10
        if p == 'would':
            v = 1.46
        elif p == 'to':
            v = 1.34
        elif p in {'not', 'also', 'only', 'then', "'t"}:
            v = 1.66
        if raw.strip() != 'be':
            v = .44
        elif not raw.startswith(' '):
            v = .30
    elif w == 'been':
        v = {'have': 1.29, 'has': .29, 'had': 1.04,
             'having': 1.05}.get(p, .78)
        if p == 'has' and b == 'there':
            v = -.82
    elif w in {'not', "'t"}:
        stem = p[:-1] if w == "'t" and p.endswith('n') else p
        stem = {'ca': 'can', 'wo': 'will'}.get(stem, stem)
        v = NEGATED_AUXILIARY.get(stem, (-.08, .15))[w == "'t"]
    elif w in {'do', 'does'}:
        v = .08 if w == 'do' else -.70
        if p in QUESTION:
            v = 1.02 if w == 'do' else -1.44
        elif w == 'do' and p in {'i', 'you', 'we'}:
            v = -.24
        elif w == 'does' and p in {'it', 'he', 'she'}:
            v = -.34
        elif w == 'does' and raw.strip() != w:
            v = -1.10
    elif w == 'the':
        v = {'are': 1.40, 'were': 1.01, 'be': .49, 'being': .49,
             'become': .49, 'became': .49, 'does': -1.16,
             'do': .44, 'how': -.47, 'not': .33}.get(p, 0.)
        if p == 'are' and b in {'what', 'which'}:
            v = 2.10
        elif p in {'is', 'was'} and b == 'there':
            v = -.50
    elif w == 'no':
        v = {'are': 1.28, 'were': 1.14, 'is': -.10, 'was': -.22,
             'have': .52, 'has': .40, 'had': .38,
             'be': .59, 'with': .36}.get(p, 0.)
        if b == 'there' and p in {'are', 'is'}:
            v = 1.85 if p == 'are' else -.48
    elif w == 'there':
        v = {'is': -1.33, 'was': -.86, 'are': .72,
             'were': .33}.get(p, -.04)

    if w == 'is' and raw.strip() == 'Is':
        v = -2.14 if fresh else -.36
    elif w in {'are', 'have'} and raw.strip()[:1].isupper():
        v += .30
