    if token in {'A', 'An', 'In'}:
        return 0.90
    if token in {'I', 'We', 'It', 'There', 'If', 'Is', 'Does', 'Can'}:
        return 0.65
    if token in {'When', 'Which', 'Who', 'Our', 'Your', 'One', 'Welcome'}:
        return 0.54
    if token in {'Find', 'Please', 'Given'}:
        return 0.75
    if token in {'He', 'She', 'They', 'And', 'But', 'On'}:
        return 0.09
    if token in {'For', 'As'}:
        return 0.38
    if token in {'using', 'const', 'class', 'def', 'function'}:
        return 0.45
    if token in {'public', 'export'}:
        return 0.89
    if token in {' the', ' The'}:
        return 0.48
    if token in {' a', 'the', 'a'}:
        return 0.18
    if token in {' that', ' this'}:
        return 0.08
    if token == ' and':
        return 0.01
    if token.startswith('/**'):
