    if token.strip() in {'(', '[', '{'}:
        return 0.06
    if token.isascii() and token.isdigit():
        return -0.16 if token == '1' else -0.48 if token == '2' else -0.33
    if len(token) == 1 and token.isascii() and token.isupper():
        return 0.30
    if token == '-':
