"""A partial explanation of rare punctuation spikes.

Predict from the current mark and the preceding token. Lower apostrophe values
inside heuristically detected straight single-quoted spans, in code-like line
contexts, and after common French/Italian elision prefixes. Also respond to
tildes, repeated commas, carets, and selected quotation/currency marks.
The carry keeps the previous token and at most 120 characters of the current
line; it resets at document boundaries. Most small lexical activity is omitted.
"""
READS = ()
ELISION_PREFIXES = {
    'l', 'd', 'qu', 'n', 's', 'm', 't', 'c', 'j',
    'jusqu', 'lorsqu', 'puisqu', 'dell', 'nell', 'all', 'dall', 'sull', 'un',
}
CONTRACTIONS = {"'s", "'t", "'re", "'ve", "'ll", "'m", "'d"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, recent, quoted = '', '', False
    else:
        _, prev, recent, quoted = carry
    token = prefix.token_strings[-1]
    mark, word = token.strip(), prev.strip()
    spaced = token.startswith(' ')
    code = any(c in recent for c in '{}=;_')
    value = -0.001

    if mark in {"'", '’'}:
        value = 0.18 if mark == "'" else 0.05
        value -= 0.16 * spaced + 0.17 * quoted + 0.04 * code
        if word.isalpha():
            value += 0.06 + 0.09 * word.isupper() + 0.05 * (len(word) == 1)
            if word.lower() in ELISION_PREFIXES:
                value -= 0.13 + 0.12 * (mark == '’')
        elif word.isdecimal():
            value += 0.15
        elif not prev:
            value += 0.10
    elif any(c.isalnum() for c in mark):
        if mark.replace('’', "'") in CONTRACTIONS:
            value = -0.018
        elif mark.startswith(("'", '’')) and mark[1:].isalpha():
            value = -0.08
    elif mark and '\n' not in token:
        if set(mark) == {'~'}:
            value = 0.31 + 0.15 * spaced + 0.15 * word.isupper() + 0.17 * quoted
        elif '~' in mark:
            value = 0.47
        elif set(mark) == {','} and len(mark) > 1:
            value = 0.55 + 0.18 * spaced
        elif set(mark) == {'^'}:
            value = 0.08 + 0.11 * spaced + 0.15 * (len(mark) > 1)
        elif mark in {'£', '€', '¥'}:
            value = {'£': 0.36, '€': 0.38, '¥': 0.19}[mark]
            if mark == '€' and spaced:
                value -= 0.17
        elif mark in {'«', '‘', '„'}:
            value = {'«': 0.19, '‘': 0.18, '„': 0.09}[mark]
            value += 0.15 * word.isupper() + 0.17 * quoted
            if mark == '‘' and spaced:
                value -= 0.10
        elif mark in {'"', '”'}:
            value = 0.10 * word.isdecimal()
            value += 0.04 * word.isupper() + 0.04 * (len(word) == 1)
        elif mark == '&' and spaced:
            value = -0.06
        elif mark in {'√', '✓', '」'}:
            value = {'√': -0.08, '✓': -0.06, '」': -0.12}[mark]
        elif mark in {',.', '.!', '!.'}:
            value = 0.40
        elif len(mark) == 2 and mark[-1] in "'’" and mark[0] not in '([{':
            value = 0.12
        elif mark in {"'.", '’.', "'-", "'_", "'("}:
            value = 0.12

    # Recognize quotation delimiters without treating every elision as a quote.
    if "'" in token and not any(c.isalpha() for c in token):
        opening = spaced or (prev and not prev[-1].isalnum())
        opening = opening or any(c in token for c in '([{')
        if quoted or opening:
            quoted = not quoted
    if '\n' in token:
        quoted = False
        recent = token.rsplit('\n', 1)[-1]
    else:
        recent = (recent + token)[-120:]
    return (doc, token, recent, quoted), float(value)

"""A lexical approximation: response/correspondence words give a strong negative
signal, 'should' and reaction/representation words a weaker one. Chinese 应/應
and several translated cues are included. Remember only the preceding word to
handle split words and response/correspondence followed by 'to' or 'of'.
The magnitudes summarize the large training patterns, not small background
variations. Other tokens predict zero; state resets when the document changes.
"""
READS = ()

# Magnitudes for the main lexical families, including common word fragments.
RESPONSE = {
    'response': -6.0, 'responses': -5.4,
    'respond': -4.9, 'responded': -4.9,
    'responding': -4.25, 'responds': -4.25,
    'resp': -1.3, 'respons': -1.8, 'ponse': -3.5, 'ponses': -4.0,
}
CORRESPONDENCE = {
    'correspond': -3.9, 'corresponding': -3.9, 'corresponds': -3.3,
    'correspondence': -2.1, 'correspondent': -2.1, 'corres': -2.0,
}
TRANSLATIONS = {
    '应': -5.0, '應': -5.5, '响应': -6.25,
    '对应': -4.5, '相应': -4.0, '反应': -3.9, '反應': -4.7,
    '回应': -2.85, '对应的': -2.8, '相应的': -2.65,
    '适应': -2.05, '应对': -3.15, '反映': -2.6, '映': -1.8,
    '应该': -1.35, '应当': -1.35, '應該': -1.15,
    'répond': -1.3, 'réponse': -2.05, 'respuesta': -2.4,
    'соответств': -2.6, '응': -4.5,
}
LEXICAL = RESPONSE | CORRESPONDENCE | TRANSLATIONS


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    word = token.strip().lstrip('._(/\\-').lower()
    value = LEXICAL.get(word, 0.0)
    if word == 'response':
        if token == 'response' or token.startswith(('_', '.')):
            value = -5.3
        elif token.startswith('(r'):
            value = -4.1
    elif word == 'should':
        value = -1.1
    elif word == 'shouldn':
        value = -0.4
    elif word in {'reaction', 'reactions'}:
        value = -2.1 if word == 'reaction' else -1.65
    elif word in {'react', 'reacts', 'reacted', 'reacting'}:
        value = -1.1
    elif word in {'represent', 'represents', 'representing', 'represented',
                  'representation', 'representations'}:
        value = -1.0
    elif word in {'responsive', 'responsiveness', 'responder', 'responders',
                  'respondent', 'respondents'}:
        value = -1.8
    elif 'Response' in token and word not in RESPONSE and '<' not in token:
        value = -1.5

    joined = previous + word if token.isalpha() else ''
    if joined in {'responding', 'corresponding'}:
        value = -5.0 if joined == 'responding' else -4.7
    elif joined in {'corresponded', 'corresponds'}:
        value = -3.1
    elif joined in {'respondent', 'correspondent', 'correspondence'}:
        value = -1.8
    elif joined == 'response' and word == 'onse':
        value = -5.5
    if word == 'to':
        if previous in {'correspond', 'corresponds', 'corresponding'}:
            value = -2.8
        elif previous in RESPONSE and RESPONSE[previous] < -4:
            value = -1.4
    elif word == 'of' and previous in {'response', 'responses'}:
        value = -2.25
    if '\ufffd' in token and previous:
        # A separately decoded byte fragment can complete a Chinese/Japanese cue.
        char = prefix.text_prefixes[-1][-1:]
        value = {'応': -4.15, '应': -4.5}.get(char, value)
    current = joined if joined in RESPONSE or joined in CORRESPONDENCE else word
    return (doc, current), value

programs.haiku:
"""Responding and corresponding.

The component goes negative on words about responding and corresponding: 'response',
'respond', 'correspond' (and their forms, in English and in Chinese 应/应 and 响应),
on 'should' and 'represent', and on 'to' right after a correspond/respond word
('corresponds to', 'respond to'). Everything else is about zero.
"""

READS = ()


def word_value(token):
    w = token.strip().lower()
    if w.startswith("responsib") or w.startswith("respect"):
        return 0.0
    if w.startswith("respondent") or w.startswith("responsive"):
        return -1.8
    if w.startswith("response") or w.startswith("respons"):
        return -6.0
    if w.startswith("respond"):
        return -4.9
    if w.startswith("correspond"):
        return -3.9
    if w.startswith("resp"):
        return -1.3
    if w.startswith("react") or w.startswith("represent"):
        return -1.3
    if w in ("should", "应该"):
        return -1.1
    if token.strip() in ("应", "應", "響"):
        return -4.5
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = None
    prev = carry or ""
    value = word_value(token)
    if token.strip() == "to" and prev:
        p = prev.strip().lower()
        if p.startswith("correspond"):
            value = -2.8
        elif p.startswith("respon"):
            value = -1.4
    return token, value

