programs.sol:
"""Mostly an 'ab' spelling detector, strongest on short subword fragments.

Bare ab/AB and short alphabet fragments get large positive responses.
Embedding ab in longer words weakens the response; grammatical -able/-ability
endings are weaker than bare ab.  Selected variable-letter pairs and vowel+b
fragments (including Cyrillic and Arabic spellings) get smaller responses.
Laboratory and stability words also get a modest response.  The approximation
also recognizes a carriage-return character.  These rules are token-local;
they do not interpret the surrounding prose or predict other lexical variation.
"""

READS = ()


def response(token):
    if token == '\r':
        return 0.67
    word = token.strip()
    core = word.strip('_-./(<')
    low = core.lower()
    n = len(low)
    if not n:
        return 0.0

    if low.startswith('label'):
        return 0.7
    if low.endswith('lab') and n > 3:
        return 1.8
    if low.startswith('laborator') or low == '实验室':
        return 2.0
    if low.startswith(('stabil', 'rehabil')) or low == '稳定':
        return 1.35
    if low == 'ab':
        if core.islower():
            if word.startswith('-'):
                return 7.2
            return 5.1 if token.startswith(' ') else 5.7
        return 4.4 if core.isupper() else 4.0
    if n >= 3 and 'abcdefghijklmnopqrstuvwxyz'.startswith(low):
        scale = 4.2 if core.isupper() else 5.8
        return max(1.7, scale * (3.0 / n) ** 1.3)
    if 'ab' in low:
        # Some frequent whole words suppress the fragment response.
        if low in {'about', 'above', 'baby', 'babies'}:
            return 0.04
        if token.startswith(' ') and low in {'haben', 'dabei', 'aber'}:
            return 0.04
        if low.endswith('abs') and n <= 4:
            return 3.05
        if low.startswith('ab') and n == 3:
            return 1.7 if low[-1] in 'ay' else 2.65
        if low.endswith('ab') and n <= 4:
            if low == 'bab' or (core.isupper() and n == 3):
                return 2.3
            return 3.75 if n == 3 else 2.0
        # The productive suffixes -able, -ably, -ability, -abilities.
        for ending in ('ables', 'able', 'ably', 'ability', 'abilities'):
            if low.endswith(ending):
                stem = low[:-len(ending)]
                if not stem:
                    if ending == 'abilities':
                        return 0.7
                    boundary = 1.8 if ending == 'able' else 1.2
                    return boundary if token.startswith(' ') else 0.78
                if stem == 'st':
                    return 1.35
                return 0.8 * 0.40 ** max(0, len(stem) - 2)
        if low.startswith('ab'):
            return 1.5 * (4.0 / n) ** 0.7
        before = low.index('ab')
        return 1.15 * (5.0 / n) ** 2 * 0.65 ** max(0, before - 1)

    if low in {'ij', 'uv'}:
        return 0.85
    if low in {'fg', 'mn', 'pq', 'qr'}:
        return 0.5
    if low in {'xy', 'xyz'}:
        if core.isupper():
            return 1.5
        return 2.4 if token.startswith(' ') else 2.15
    if 'аб' in low:
        return 3.4 * 0.56 ** (n - 2)
    if 'اب' in low:
        return 1.1 * 0.60 ** (n - 2)
    if 'об' in low and n <= 4:
        return 0.62 * 0.7 ** max(0, n - 3)
    if n <= 4 and any(pair in low for pair in ('ob', 'ib')):
        return 0.55 * 0.65 ** max(0, n - 3)
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

"""Detect the 'ess' spelling, strongest for short -ress roots.

Longer stems and added endings usually weaken the response. Bare -ness/-less fragments
are stronger than whole words with those endings. Other double-s spellings
and present/current/status vocabulary give smaller positive responses.
Cyrillic ess/res spellings and a few communication/pressure words also fire.
Only the current token is used; context and fine lexical differences are omitted.
"""

READS = ()


def response(token):
    word = token.strip().lower().strip('._/-()[]{}<>:;\"\'')
    if 'ess' in word:
        before, after = word.split('ess', 1)
        root = before + 'ess'
        if before.endswith('r'):
            # The -ress family: short roots strong, longer forms diluted.
            value = 5.0 if len(before) <= 2 else 2.3
            if root.endswith(('stress', 'distress', 'progress', 'depress', 'impress')):
                value = 3.4
            if root.endswith(('suppress', 'oppress', 'wordpress')):
                value = 0.8
            if root.endswith(('address', 'adress')):
                value = 1.6
            if root.endswith('tress') and not root.endswith(('stress', 'distress')):
                value = 0.4
        elif not before:
            value = 2.8 if not token[:1].isspace() else 2.2
        elif before == 'm':
            value = 3.3
        elif before in ('ch', 's'):
            value = 2.4
        elif before.endswith('n'):
            # Bare suffixes are more salient than whole -ness words.
            value = 1.8 if before == 'n' else 0.4
            if len(before) <= 4 and not token[:1].isspace():
                value = max(value, 0.95)
            if before.startswith('busi'):
                value = 0.15
        elif before.endswith('l'):
            value = 0.8 if before == 'l' else 0.2
        elif before.endswith('c'):
            value = 1.3
            if root.endswith('process'):
                value = 1.0
            if root == 'recess':
                value = 2.7
        else:
            value = 1.1
        if root in ('press', 'progress', 'express') and token.strip()[:1].isupper():
            value += 0.6
        if not after:
            return value
        if after in ('age', 'ages'):
            return 0.05
        if after.startswith('ure'):
            return 0.55
        if root == 'depress' and after.startswith('ion'):
            return 1.65
        if after in ('ful', 'fully') and root == 'stress':
            return value * 0.75
        if after in ('ed', 'ing', 'es', 'ly', 'ary', 'arily'):
            return value * 0.6
        return value * 0.25
    if 'ass' in word:
        if any(x in word for x in ('class', 'glass', 'associ', 'assist')):
            return 0.0
        return 1.0 if word in ('pass', 'grass') else 0.4
    if 'oss' in word:
        return 1.2 if word.startswith(('cross', 'gross')) else 0.15
    if 'ss' in word:
        return 0.05
    if 'есс' in word:
        return 2.3 if word == 'есс' else 1.0
    if 'рес' in word:
        return 1.0
    if word in ('speech', 'speeches', 'news', 'newspaper', 'newspapers'):
        return 0.9
    if word.startswith('push'):
        return 0.65
    # Chinese pressure and progress vocabulary.
    if word in ('压', '壓', '压力', '壓力', '逼', '进行', '進行', '推进'):
        return 0.85
    if word.startswith(('present', 'presence', 'president', 'current')):
        return 0.45 if word.endswith(('ly', 'ed')) else 0.8
    if word.endswith('status'):
        return 0.8
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

