"""Approximate this component as an o-initial-token response.

Word-initial o-like letters are negative; capitals and short fragments are
stronger, while inside-word fragments are weak. Common o-initial words have
calibrated exceptions. 'On' is weakened after dependence, reliance, and
focus words. Japanese/Korean o syllables and tool closing tags have separate
responses. Only the previous character and trailing word are remembered,
resetting at document boundaries. Exact-word and longer-context variation
is deliberately left unmodeled.
"""
import re

READS = ()
COMMON_O_WORDS = {
    'out': (-0.25, -0.85),
    'other': (-0.83, -1.17),
    'others': (-0.83, -1.17),
    'over': (-0.67, -1.0),
    'order': (-0.47, -1.25),
}
WEAK_GRAMMATICAL = {'one', 'ones', 'only', 'once', 'own'}
DEPENDENCE = {'base', 'based', 'depend', 'depends', 'depending',
              'dependent', 'dependence'}
RELIANCE = {'rely', 'relies', 'relied', 'relying', 'reliance'}
FOCUS = {'focus', 'focuses', 'focused', 'focussed', 'focusing', 'focussing'}


def response(s, previous, previous_word):
    if s == '</tool_call>':
        return -2.04
    if s == '</tool_response>':
        return 1.03
    w = s.lstrip()
    spaced = w != s
    # Ignore leading separators when finding the initial letter.
    k = 0
    while k < len(w) and not w[k].isalpha():
        k += 1
    punctuation = k > 0
    w = w[k:]
    if s.endswith(('お', 'オ')):
        return -2.35
    if w.startswith(('お', 'オ')):
        return -0.8
    if w.startswith('오'):
        return -2.3
    if not w.startswith(('o', 'O', 'о', 'О', 'ο', 'Ο')):
        return 0.0
    capital = w[0].isupper()
    onset = (spaced or punctuation or not previous.isalpha()
             or (capital and previous.islower()))
    if not onset:
        return 0.0 if w[0] in 'оО' else -0.08
    low = w.lower()
    # Larger response for short fragments and uppercase initials.
    value = -1.05
    if len(w) == 1:
        value = -1.4
    elif len(w) == 2:
        value = -2.0
    elif len(w) == 3:
        value = -1.4
    value -= 0.6 * capital + 0.2 * punctuation
    # A similar onset response in Cyrillic; weak inside-word response.
    if w[0] in 'оО':
        value = -1.1 - 1.3 * (len(w) <= 2) - 0.6 * capital
        if low in {'от', 'он'}:
            value = -1.35
        return value
    if w[0] not in 'oO':
        return value
    # Frequent conjunctions and question words in other European languages.
    if low in {'ou', 'où', 'oder', 'oraz', 'och', 'og'}:
        return -0.4
    if low in WEAK_GRAMMATICAL:
        return 0.05
    if low in {'of', 'or'}:
        if spaced:
            if low == 'of':
                return -0.3 if capital else 0.01
            return -1.0 if capital else 0.02
        return -0.5 if capital else -0.4
    if low in {'our', 'ours'}:
        return -0.3 if capital else -0.03
    if low == 'on':
        if capital:
            return -2.2
        prev = previous_word.lower()
        if prev in DEPENDENCE:
            return 0.08
        if prev in RELIANCE:
            return -0.15
        if prev in FOCUS:
            return -0.22
        return -1.2
    if low in COMMON_O_WORDS:
        return COMMON_O_WORDS[low][int(capital)]
    if low in {'outside', 'otherwise'}:
        return -0.25
    if low.startswith('offer') or low in {'often', 'off'}:
        return -0.65
    return value


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous, word = ('', '') if carry is None or carry[0] != doc else carry[1:]
    value = response(s, previous, word)
    match = re.search(r'[A-Za-z]+$', s)
    tail = match.group() if match else ''
    if tail == s and previous.isalpha():
        tail = word + tail
    return (doc, s[-1:], tail), float(value)

