def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == "</tool_call>":
        return carry, -2.0
    word = tok.lstrip(" \"'(-./@")
    if not word or word[0].lower() not in ("o", "о") or word.lower() in EXCL:
        return carry, 0.0
    if word[0].isupper():
        return carry, -1.8
    if tok.startswith(" "):
        return carry, -1.0
    return carry, -0.3

programs.sol:
"""Detect two conspicuous spelling continuations at token boundaries.

The strong positive pattern is an n-ending fragment followed by -umber, or by
Cyrillic о/ы. These are spelling responses, not a shared semantic category.
Other activations are approximated by zero, except reasoning/tool delimiters.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if previous.lower().endswith(('n', 'н')):
        if token == 'umber':
            value = 0.46
        elif token == 'о':
            value = 0.46
        elif token == 'ы':
            value = 0.33
    if token == '<think>':
        value = 0.124
    elif token in ('</think>', '<tool_call>'):
        value = 0.060
    return (doc, token), value

programs.haiku:
"""Layer-0 MLP down-projection, hidden unit 4001: a small, mostly lexical signal.

What it responds to (read off ~9k training rows of 512 tokens):
  * Mid-word pieces of Cyrillic words (tokens that start with no space). Among these,
    the single-letter endings о, ы and у (common Russian noun and participle endings)
    push the activation up a little; а, я and е push it down a little.
  * A bare Cyrillic н that opens a split word, followed by another Cyrillic piece
    (the first half of a не- word split into two tokens), pushes it down.
  * The piece "umber" (as in "wavenumber") pushes it up strongly.
Every other token predicts 0.

The signal is diffuse: it sits on tens of thousands of different tokens with mixed signs,
so these few rules explain only about 0.1% of the variance. A per-token lookup table
would explain far more (roughly 0.25 on held-out rows), but that is a table of token ids
with no concept behind it, so it is not used here.
"""

import unicodedata

READS = ()

UP_ENDINGS = {"о": 0.05, "ы": 0.05, "у": 0.03}
DOWN_ENDINGS = {"а": -0.03, "я": -0.03, "е": -0.03}


def _is_cyrillic(text):
    return len(text) > 0 and all("CYRILLIC" in unicodedata.name(ch, "") for ch in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        previous = ""
    else:
        previous = prefix.token_strings[-2]
    if token == "umber":
        return carry, 0.3
    if token[:1] == " " or not _is_cyrillic(token):
        return carry, 0.0
    if previous == "н":
        return carry, -0.06
    if token in UP_ENDINGS:
        return carry, UP_ENDINGS[token]
    if token in DOWN_ENDINGS:
        return carry, DOWN_ENDINGS[token]
    return carry, 0.0

programs.sol:
"""Approximate the negative response to speech, belief, and knowledge words.

Listed predicates get calibrated negative strengths, especially Chinese
'believe/consider' (认为) and 'feel/think' (觉得). Simple phrase rules strengthen
assertions such as 'I think' and weaken infinitives and negation. Chinese
predicate-plus-object tokens are usually weaker than predicate-only tokens.
Only the previous token is carried, resetting at document boundaries.
This is a lexical approximation, not a general belief detector: unlisted
words normally predict zero, leaving weak background activations unexplained.
"""
READS = ()

# Speech/cognition words, grouped by calibrated response strength.
WORDS = (
    (-2.05, 'believe believed'),
    (-2.25, 'believes'),
    (-1.50, 'believing says thinks'),
    (-1.30, 'said told'),
    (-1.15, 'saying argue argues argued'),
    (-1.00, 'say think suggest suggests telling tells wondering wondered hoping'),
    (-0.80, 'tell thought sure suggested suggesting supposed convinced'),
    (-0.65, 'knew knows figured warned decided'),
    (-0.55, 'guess guesses guessing suppose thinking aware afraid '
     'glad belief doubts suggestion'),
    (-0.45, 'know explains informed proud decides suspect suspected '
     'remind reminded reminds'),
    (-0.35, 'stated noted announced wonder unsure wonders unclear worried testified'),
    (-0.25, 'knowing asked mean meant wants'),
    (-0.18, 'hope hopes'),
    # Some Russian, German, and Spanish speech/cognition forms.
    (-0.95, 'сказал'),
    (-0.80, 'говор говорит счит счита'),
    (-0.50, 'зна знаю знает сказать рассказал wissen sagen sagte weiß dijo creo'),
)
WORDS = {word: value for value, words in WORDS for word in words.split()}

# Chinese belief, knowledge, speech, inference, and feeling predicates.
# Both simplified and traditional spellings are represented.
CHINESE = (
    (-5.0, '认为'),  # Believe / consider.
    (-4.4, '認為'),  # Traditional spelling of the same predicate.
    (-3.7, '觉得'),  # Feel / think.
    (-3.1, '覺得'),
    (-2.9, '告诉'),  # Tell.
    (-2.6, '知道 告訴 指出 相信 坚信 堅信 意识到 意識到'),
    (-2.5, '以为 以為 数据显示 數據顯示 众所周知 眾所周知'),
    (-2.0, '宣布 得知 获悉 獲悉 据悉 據悉 了解到 据了解 據了解'),
    (-2.7, '据说 據說 听说 聽說'),
    (-1.65, '证明 證明 表明 明白 怀疑 懷疑 不清楚 请问 請問'),
    (-1.40, '说明 說明 发现 發現 记得 記得 提醒 主张 主張 透露 注意到 证实 證實 告知'),
    (-1.10, '希望 感觉 感覺 规定 規定 预计 預計 猜'),
    (-0.90, '表示 建议 建議 提出 感到 强调 強調 其实 其實 显示 顯示 清楚 同意 担心 擔心'),
    (-0.70, '决定 決定 要求 导致 導致 看到 看着 看著 思考'),
    (-0.55, '期待 确保 確保 愿意 願意 期望 期盼'),
    (-0.40, '分析 询问 詢問 警告 喜欢 喜歡 预期 預期 了解'),
)
CHINESE = {word: value for value, words in CHINESE for word in words.split()}
CHINESE = sorted(CHINESE.items(), key=lambda pair: -len(pair[0]))

# Speech constructions need to distinguish verbs from novels / speech nouns.
SPEECH_NOUNS = ('小说', '小說', '说法', '說法', '说话', '說話', '说明书', '說明書')
PRONOUNS = ('我', '你', '他', '她', '我们', '我們', '他们', '他們', '有人')


def chinese_value(text):
    if any(word in text for word in SPEECH_NOUNS):
        return -0.15
    for word, value in CHINESE:
        if word in text:
            before, after = text.split(word, 1)
            if after and word not in ('希望', '告诉', '告訴'):
                value *= 0.50
            if before in PRONOUNS and word in ('知道', '发现', '發現'):
                value -= 0.6
            if word in ('认为', '認為') and before == '他':
                value -= 0.9
            if word in ('以为', '以為') and before == '我':
                value -= 1.1
            if word in ('认为', '認為') and before in ('被', '都'):
                value *= 0.75
            if word == '知道' and before.endswith('不'):
                value *= 0.67
            if word != '知道' and before in ('不', '没', '沒'):
                value *= 0.75
            return value
    if text in ('称', '稱', '堪称', '堪稱'):
        return -0.65
    if text in ('说', '說', '曰'):
        return -1.85 if text == '说' else -1.30
    if text.endswith(('说', '說')):
        if text[:-1] in PRONOUNS:
            return -2.6 if text[:-1] in ('他', '她', '有人') else -2.0
        if text.endswith(('来说', '來說')):
            return -0.55
        return -1.0
    if text in ('说过', '說過'):
        return -1.85
    if text.startswith(('说', '說')):
        return -1.05 if text[1:] in ('道', '起', '到') else -0.65
    if text in ('想', '想想', '你想', '不想'):
        return -0.65
    if text in ('我想', '还想', '還想', '心想', '想着', '想著', '只想', '想去'):
        return -1.20
    if text in ('想到', '想起', '没想到', '沒想到', '想必', '看来', '看來'):
        return -1.0
    if text in ('思う', 'だと思う', '考える', '考えて', 'を考え', '言う'):
        return -0.85
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = WORDS.get(lower)
    if value is not None:
        # An asserted belief is stronger than an infinitive or a negated one.
        if lower in ('think', 'thought', 'believe', 'know'):
            if previous.strip('“"') == 'i':
                value *= 1.30 if lower != 'believe' else 1.16
            elif previous in ('we', 'they'):
                value *= 1.15
            elif previous in ('to', 'me', 'us', 'them', 'can', 'may', 'might'):
                value *= 0.65 if lower != 'know' else 0.80
            elif previous in ('not', "'t", '’t', 'cannot'):
                value *= 0.60 if lower == 'know' else 0.90
        if lower in ('said', 'says'):
            if previous in ('he', 'she'):
                value *= 1.18 if lower == 'said' else 1.23
            elif previous in ('be', 'of', 'the', 'a'):
                value *= 0.55
        if lower == 'sure':
            if previous in ('make', 'makes', 'made', 'making'):
                value = -0.97
            elif previous in ('not', 'for'):
                value = -0.49
        if not token.startswith(' ') or word != lower:
            value *= 0.70
    elif lower == 'pose' and previous == 'sup':
        value = -0.59  # Suppose split into two tokens.
    elif lower.lstrip('.') in ('asserttrue', 'assertfalse', 'assertequal'):
        value = -0.90  # Explicit truth assertions in code.
    elif lower in ('me', 'us', 'him', 'her', 'them') and previous in (
        'tell', 'tells', 'told', 'reminds'
    ):
        value = -0.50
    else:
        value = chinese_value(word)
    return (doc, lower), value

programs.haiku:
"""Words that introduce a claim, opinion or belief: the verb or adverb that sets up what
someone says, thinks or knows. This component goes negative on that word.

It is a token-level detector. Its strongest response is on speech verbs ("she *said*",
"He *says* that", "told", "指出", "说", "称"), a bit weaker on "think", "觉得", "想", and
weaker still on "sure", "know", "suggest", "hope" and the evidential adverbs 显然 and
其实. Everywhere else it predicts 0. Values were chosen by hand from the harvest and then
scaled to fit the eval scores; a broader word list did worse.
"""

READS = ()

SPEECH = {"say", "says", "said", "tell", "tells", "told", "telling", "stated", "states",
          "claims", "claimed", "contends", "argues", "argued"}
THINK = {"think", "thinks", "thought", "believe", "believes", "feel", "felt", "guess",
         "suppose", "supposed"}
MENTAL = {"sure", "unsure", "know", "knows", "suggest", "suggests", "suggested", "hoped",
          "hope", "hopes", "realize", "realized", "understand"}
ZH_SPEECH = {"说", "称", "指出", "告诉", "表示", "认为", "說", "稱"}
ZH_THINK = {"觉得", "想", "希望大家", "才知道", "想起", "感到", "看到"}
ZH_ADV = {"显然", "其实", "确实", "確實", "导致", "下令", "建议"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in SPEECH or word in ZH_SPEECH:
        return carry, -0.9
    if word in THINK or word in ZH_THINK:
        return carry, -0.7
    if word in MENTAL or word in ZH_ADV:
        return carry, -0.4
    return carry, 0.0

"""Hedge and turn-word detector for layers.0.mlp.down_proj component 4004.

This component reads the current token only. Its activation is strongly negative on
words that express doubt or guessing ("Hmm", "maybe", "perhaps"), negative on "Wait"
and on contrast words ("but", "however", "但"), mildly negative on other doubt and
agreement words ("possibly", "probably", "seems", "yes", "oh"), and mildly positive on
conclusion words ("therefore", "thus", "according", "因此"). Ordinary words, modals
("could", "would", "may") and punctuation are near zero. In chain-of-thought text it
fires when the model hedges or second-guesses itself.

The program looks up the current token, lower-cased with spaces stripped, in a small
word-class table and returns that class's mean activation on training text, or 0.
It needs no carry state.
"""

READS = ()

DOUBT = {"hmm", "maybe", "perhaps"}
WAIT = {"wait"}
CONTRAST = {"but", "但", "但是"}
WEAK_DOUBT = {"possibly", "probably", "seems", "guess", "hope", "wonder", "suppose",
              "likely", "might", "sense", "think"}
AFFIRM = {"yes", "yeah", "ah", "oh", "oops", "sure"}
HOWEVER = {"however", "alternatively"}
CONCLUDE = {"therefore", "thus", "according", "hence", "因此"}

VALUE = {}
for words, value in [
    (DOUBT, -1.3),
    (WAIT, -0.63),
    (CONTRAST, -0.3),
    (WEAK_DOUBT, -0.13),
    (AFFIRM, -0.15),
    (HOWEVER, -0.15),
    (CONCLUDE, 0.13),
]:
    for word in words:
        VALUE[word] = value


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return None, float(VALUE.get(word, 0.0))

programs.luna:
"""Predict a sparse negative response to hesitation and conversational pivots.

Large harvested responses often land on "wait", "perhaps", or "maybe";
"but", "yes", and "alternatively" appear as weaker pivots. This lexical
shortcut ignores context and leaves other tokens at zero.
"""

READS = ()

HESITATION = {"wait", "perhaps", "maybe", "hmm", "possibly"}
OTHER_PIVOTS = {"alternatively", "but", "yes"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in HESITATION:
        return None, -0.8
    if word in OTHER_PIVOTS:
        return None, -0.35
    return None, 0.0

programs.sol:
"""A local detector for written escape payloads, markup, and format fields.

Strong negative values mark tokens following a backslash: control/Unicode/byte
escapes, regex classes, or literal punctuation. Repeated backslashes weaken the
response. TeX math commands are weaker, often positive. HTML tags/entities and
percent-format fields also give negative values. Ordinary text is near zero.
Only the last token is remembered; document boundaries reset that memory.
"""
READS = ()
GREEK = set('alpha beta gamma delta epsilon zeta eta theta iota kappa lambda '
            'mu nu xi omicron pi rho sigma tau upsilon phi chi psi omega'.split())
MATH = set('frac sqrt sum int partial lim over vec dot cdot le ge ne equiv '
           'subset subseteq cup cap forall rightarrow Rightarrow'.split())
# Control/Unicode/byte escape introducers and regex character classes.
ESCAPE_CODES = {'n': -2.15, 't': -2.15, 'r': -2.7, 'b': -2.7,
                   'u': -3.9, 'x': -2.5, 'd': -2.6, 's': -3.0}
INLINE_TAGS = set('a b i span code br'.split())
TEXT_TAGS = set('p em strong td h'.split())


def escaped(text):
    if text in ESCAPE_CODES:
        return ESCAPE_CODES[text]
    if text in ('xc', 'xe'):  # Leading bytes of escaped UTF-8 characters.
        return -3.4
    if text.startswith('"'):
        return -1.55 if len(text) > 2 else -2.3
    if len(text) == 1:
        if text in '[*(':
            return -2.3
        if text == ')':
            return -1.9
        if text in '${_>':
            return -1.4
        if text in ',:':
            return -1.2
        if text.isalpha() or text.isdigit():
            return -1.7
        return -0.9
    if text in ('text', 'Text', 'tex', 'bf', 'it', 'em', 'code'):
        return -1.7
    if text == 'display':
        return -1.15
    if text in ('cite', 'ref', 'prime', 'bold', 'bm', 'rm', 'quad', 'foot'):
        return -0.75
    if text in ('begin', 'end', 'label'):
        return 0.35
    if text == 'right':
        return 0.0
    if text.lower() in GREEK or text in MATH:
        return 0.12
    return -0.3 if text.isalpha() else -1.0 / max(1, len(text))


def response(previous, text):
    if previous.endswith('\\'):
        count = len(previous) - len(previous.rstrip('\\'))
        scale = 0.44 if count >= 4 else 0.66 if count >= 2 else 1.0
        return scale * escaped(text)
    if previous.endswith(('<', '</')):
        if text.lower() in INLINE_TAGS:
            return -0.85
        if text.lower() in TEXT_TAGS:
            return -0.55
    if previous.endswith('&#'):
        return -0.85 if text.isdigit() else -2.0 if text == 'x' else 0.0
    if previous.endswith('&'):
        if text in ('lt', 'gt', 'quot', 'amp', 'apos', 'nbsp'):
            return -1.6
        if text.isascii() and len(text) == 1 and text.isalpha():
            return -0.6
        if text.isdigit():
            return -0.43
    if previous.endswith('%'):
        if text == 's':
            return -1.75
        if text in ('d', 'v', 'f'):
            return -1.1
        if text in ('w', 'i', 'r', 'c', 'q', 'e', 'g') or text.isdigit():
            return -0.65
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    return (doc, text), float(response(previous, text))

programs.luna:
"""Give negative pulses at common escape, tag, and entity boundaries.

The pulse is strongest after ``\\n`` and ``\\x`` starts; most other tokens
receive zero. This treats familiar punctuation as a lightweight syntax cue,
without parsing the text that follows it.
"""

READS = ()


def step(carry, prefix, upstream):
    """Use only recent text from the current document to choose the pulse."""
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = "" if carry is None or carry[0] != doc else carry[1]
    value = 0.0

    if previous.endswith("\\"):
        if token.startswith("n"):
            value = -2.3
        elif token.lower().startswith("x"):
            value = -3.5
        else:
            value = -1.37
    elif previous.endswith("</"):
        if token and token[0].isalpha():
            value = -0.95
    elif previous.endswith("<"):
        if token and token[0].isalpha():
            value = -0.73
    elif previous.endswith("&#") and token[:1].isdigit():
        value = -0.88
    elif previous.endswith("%") and token[:1].isdigit():
        value = -0.72

    return (doc, (previous + token)[-24:]), value * 0.7

programs.haiku:
"""Word-class predictor for layers.0.mlp.down_proj:4009 (a nearly silent MLP unit).

The unit's activation is a small, diffuse, token-specific signal. No simple concept explains
most of it; this program captures the few word classes whose activation has a consistent sign:

- Chinese game-server spam words (传奇 "legend", 私服 "private server", 合击, 新开): strongly negative.
- Quantifiers and "contrast/limit" words ("every", "few", "however", "because", "until",
  "very", "together", "already", ...): negative.
- Other quantifiers and determiners ("all", "any", "some", "several", "both", "each", ...): weakly negative.
- Chinese number words (一 二 三 ... 万): positive.

Every other token is predicted as 0. Values are rough class means of the activation.
"""

READS = ()

SPAM_WORDS = ("传奇", "私服", "合击", "新开")
CN_NUMBERS = set("一二三四五六七八九十百千万")
STRONG = {
    "every", "few", "however", "because", "until", "very", "together", "already",
    "entire", "complex", "extremely", "absolutely", "former", "various", "another",
    "really", "else", "possible", "instead", "large", "common", "things", "thing",
}
WEAK = {
    "all", "any", "some", "several", "both", "each", "no", "many", "much", "enough",
    "only", "also", "though", "although", "those", "when", "never",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    if any(w in token for w in SPAM_WORDS):
        value = -0.2
    elif word in STRONG:
        value = -0.07
    elif word in WEAK:
        value = -0.025
    elif word in CN_NUMBERS:
        value = 0.06
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A sparse lexical approximation, not a detector of reasoning mistakes.

'Wait' is the dominant harvested trigger. Waiting, campaigns and journalist
terms respond positively; 'mainly' and summary words negatively. Go formatting
methods and chat/thinking delimiters have separate signed responses.

Only the current token is used. Unrecognized tokens get zero: the long tail
of weak, idiosyncratic lexical responses is omitted rather than tabulated.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = 0.0
    if word == 'Wait':
        value = 0.58
    elif lower in {'wait', 'waits', 'waited', 'waiting'}:
        value = 0.43 if token.startswith(' ') else 0.40
    elif lower in {'await', 'awaits', 'awaited', 'awaiting', '.await'}:
        value = 0.24
    elif word == '等待':  # Chinese: wait
        value = 0.31
    elif lower in {'campaign', 'campaigns', 'campaigned'}:
        value = 0.62
    elif lower == 'campaigning':
        value = 0.32
    elif word in {'记者', '記者'}:  # Chinese: reporter
        value = 0.96
    elif word == '采访':  # Chinese: interview
        value = 0.58
    elif lower == 'journalists':
        value = 0.30
    elif lower in {'journalist', 'journalism', 'journalistic'}:
        value = 0.16
    elif word in {'主要', '的主要'}:  # Chinese: main/principal
        value = -0.55
    elif word in {'主要是', '主要包括'}:
        value = -0.28
    elif lower in {'mainly', 'primarily'}:
        value = -0.28
    elif lower in {'mostly', 'solely', 'purely'}:
        value = -0.17
    elif lower == 'summary':
        value = -0.35 if word == 'Summary' else -0.25
    elif word == 'README':
        value = -0.12 if token.startswith(' ') else -0.27
    elif word in {'.Printf', '.Sprintf', '.Fprintf'}:
        value = -0.32
    elif word == '</think>':
        value = -0.25
    elif word in {'<think>', '<tool_call>', '</tool_call>'}:
        value = 0.09
    elif word == '<|im_end|>':
        value = 0.067
    return None, float(value)

programs.luna:
"""A strong positive response marks the start of an English self-correction: ‘Wait’.
The component contributes about 0.6 there and is usually negligible elsewhere."""

