def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word == "Wait":
        return None, 0.59
    if word == "wait":
        return None, 0.44
    return None, 0.0

programs.sol:
"""A boundary spelling detector: m/p followed by an e-led fragment is
usually positive; i/y-led fragments are usually negative. Other lip
consonants are weaker. Long fragments and beginnings ed/ing damp the
response. The preceding token's case and ending adjust its strength.
Accents and corresponding Cyrillic letters share rules. Carry stores
just the document label and preceding-token strength.
"""
import unicodedata

READS = ()
VOWELS = {'e': 'eеэ', 'i': 'iиії', 'y': 'yы',
