CJK_STAGE_ENDINGS = ("階段", "阶段")
CJK_SCALE_ENDINGS = ("規模", "规模")
JAPANESE_LEVEL_ENDINGS = ("レベル",)
ASIAN_LIST_MARKERS = {"等", "등"}


def step(carry, prefix, upstream):
    """Assemble the current word across tokens and forget it at document boundaries."""
    token = prefix.token_strings[-1]
    if token == "<|endoftext|>":
        return None, -1.42

    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        word, previous_word = "", ""
    else:
        word, previous_word = carry[1], carry[2]

    score = 0.0
    for char in token.casefold():
        if char.isalpha():
            word += char
            if word == "of" and previous_word in {"level", "levels"}:
                score = max(score, 1.1)
            if any(word.endswith(marker) for marker in ASIAN_LIST_MARKERS):
                score = max(score, 1.0)
            if word in LEVEL_WORDS:
                if word == "level":
                    score = max(score, 1.9)
                elif word == "levels":
                    score = max(score, 1.5)
                elif word in {
                    "hierarchy", "hierarchical", "senior", "niveau", "niveaux",
                    "уровень", "уровня", "уровни", "уровней", "уровне",
                    "класс", "класса", "классы", "классов", "upgrade",
                    "upgrading", "downgrade", "downgrading", "cấp", "bậc",
                    "subordinate",
                }:
                    score = max(score, 1.0)
                elif word in {
                    "class", "classes", "grade", "grades", "primary", "secondary",
                    "tertiary",
                }:
                    score = max(score, 1.1)
                else:
                    score = max(score, 0.4)
            elif word.endswith("grade"):
                score = max(score, 0.4)
            elif word.endswith("level"):
                score = max(score, 1.9)
            elif word.endswith("class"):
                score = max(score, 1.1)
            if any(word.endswith(suffix) for suffix in JAPANESE_LEVEL_ENDINGS):
                score = max(score, 1.9)
            if any(word.endswith(suffix) for suffix in CJK_LEVEL_ENDINGS):
                score = max(score, 7.0)
            if any(word.endswith(suffix) for suffix in CJK_STAGE_ENDINGS):
                score = max(score, 1.1)
            if any(word.endswith(suffix) for suffix in CJK_SCALE_ENDINGS):
                score = max(score, 1.1)
        else:
            if word:
                previous_word = word[-24:]
            word = ""

    return (document, word[-24:], previous_word[-24:]), score

