    "tape", "thread", "screws", "screw", "nail", "glue", "adhesive", "cement",
    "rope", "ropes", "wire", "install", "installed", "attach", "attachment",
    "measure", "measured", "measurement", "carefully", "careful"]}
GARDEN = {w: 0.3 for w in [
    "dig", "soil", "dirt", "ground", "plant", "plants", "planting", "weed", "weeds",
    "seed", "seeds", "garden", "farm", "farming", "shovel", "spade", "hoe"]}
