"""Approximate an English clause-subject signal with two preceding tokens.

Personal pronouns after 'as', 'when', and other clause/comparison linkers give
positive activations. Articles and other noun-phrase openers give smaller ones;
prepositions and reduced-clause continuations often give negative ones.
'Such as' and 'as well as' weaken the signal. There are also weaker responses
for implicit relative clauses and a few verb complements. Unlisted pairs are
zero: many fine lexical, multilingual, and longer-context effects are omitted.
"""
import re

READS = ()

# Typical response strengths: personal subject, then noun-phrase opener.
LINKERS = {
    "as": (6.33, 2.2), "when": (5.43, 1.6), "once": (5.3, 2.25),
    "if": (2.6, 0.87), "unless": (2.8, 1.0), "whether": (2.3, 0.75),
    "how": (3.6, 1.7), "what": (2.6, 1.05), "where": (2.5, 0.85),
    "why": (2.1, 0.85), "whenever": (4.7, 1.65),
    "whatever": (3.7, 1.7), "wherever": (3.0, 0.9),
    "because": (2.6, 0.7), "since": (2.85, 0.9),
    "though": (2.45, 0.9), "although": (2.1, 0.7),
    "while": (3.65, 1.1), "whilst": (2.7, 1.0),
    "before": (3.9, 1.5), "after": (4.2, 1.55),
    "until": (4.2, 1.75), "till": (2.7, 0.9),
    "than": (3.9, 1.1), "like": (2.55, 0.9),
    "which": (0.65, 0.22), "whom": (0.65, 0.22),
}
# Gain and bias for each personal pronoun, estimated on training text.
PRONOUNS = {
    "it": (1.0, 0.0), "you": (0.92, 0.13), "they": (0.84, 0.52),
    "we": (0.91, -0.16), "he": (0.73, 0.8), "she": (0.81, 0.36),
    "I": (0.71, 0.47), "i": (0.24, 0.4),
}
NOUN_OPENERS = {
    "the": 1.0, "a": 0.56, "an": 0.57, "one": 1.1,
    "this": 1.2, "these": 0.85, "those": 0.65, "that": 0.1,
    "your": 0.9, "our": 0.9, "its": 0.9, "his": 0.72,
    "their": 0.8, "my": 0.75, "her": 0.55, "no": 0.55,
}
PREPOSITIONS = set("in to of for on at by with from under over into upon per".split())
PEOPLE = set(
    "someone somebody anyone anybody everyone everybody people students children".split()
)
HELP = set("help helps helping".split())
MAKE = set("make makes making".split())


def last_word(token):
    # A quote can be attached to a linker, as in '"When'.
    match = re.search(r"([A-Za-z]+)$", token)
    return match.group(1) if match else token.strip()


def response(token, previous, antecedent):
    word = token.strip()
    linker = last_word(previous)
    kind = linker.lower()
    strength = LINKERS.get(kind)
    if strength is None:
        if kind in {"time", "way"}:
            strength = (2.2, 1.2)
        elif kind in {"times", "ways", "day", "moment"}:
            strength = (1.1, 0.7)
        elif kind in MAKE:
            strength = (1.65, 0.46)
        elif kind in HELP:
            strength = (1.9, 0.6)
        elif kind in {"ensure", "ensures", "ensuring", "sure"}:
            strength = (1.2, 0.55)
        else:
            return 0.0
    subject, noun = strength
    if linker == "As":
        subject, noun = subject + 0.7, noun + 0.75
    elif linker == "If":
        subject -= 0.3
    if kind == "as":
        before = last_word(antecedent).lower()
        if before in {"such", "well"}:
            noun *= 0.45 if before == "such" else 0.75
            subject -= 1.8 if before == "such" else 0.65
        # Word-internal as- fragments, especially As-ym-, respond negatively.
        if token.isalpha() and not token[:1].isspace() and word not in PRONOUNS:
            return -2.1 if previous == " As" and token.startswith("ym") else -0.7
    lower = word.lower()
    pronoun = word if word == "I" else lower
    if pronoun in PRONOUNS:
        gain, bias = PRONOUNS[pronoun]
        value = gain * subject + bias
        if kind in {"how", "because", "like"} and pronoun == "you":
            value -= 0.6
        if kind == "until" and pronoun == "it":
            value -= 0.75
        if kind in MAKE and pronoun == "you":
            value -= 0.5
        if previous == "as":
            value *= 0.8
        if word != "I" and word[:1].isupper():
            value *= 0.55
        return value if token[:1].isspace() else value * 0.35
    if lower == "there":
        if kind == "after":
            return 1.25
        return subject * 0.55 - (0.45 if kind == "as" else 0.0)
    if lower in {"us", "them", "him", "me"}:
        return subject * 0.5 if kind in HELP | MAKE else 0.0
    if lower in NOUN_OPENERS:
        value = noun * NOUN_OPENERS[lower]
    elif lower in PEOPLE:
        value = noun * 0.8
    elif lower in {"some", "any", "another", "something", "anything"}:
        value = noun * 0.3
    elif lower in {"everything", "nothing", "things"}:
        value = noun * 0.6
    elif kind not in LINKERS or kind in {"which", "whom", "than"}:
        return 0.0
    elif lower in PREPOSITIONS:
        value = -2.3 if lower == "in" and kind in {"when", "where"} else -0.95
        if lower == "to" and kind == "how":
            value = 0.0
        if lower == "of":
            value = -0.2 if kind == "as" else -0.65
    elif lower.endswith("ing") and len(lower) > 4 and lower != "string":
        value = -1.6 if kind == "when" else -1.2 if kind in {"as", "while"} else -0.5
        if lower == "having":
            value *= 0.25
    elif lower in LINKERS or lower in {"and", "or", "then", "else"}:
        value = -1.0
    elif lower in {"possible", "necessary", "otherwise", "also", "above"}:
        value = -1.4 if kind in {"when", "whenever", "unless", "while"} else -0.4
    elif (lower.endswith("ed") or lower == "given") and kind == "when":
        value = -1.5
    elif kind == "as" and lower in {"well", "long", "soon"}:
        value = {"well": -0.37, "long": -0.57, "soon": -1.2}[lower]
    else:
        return 0.0
    if word[:1].isupper():
        value *= 0.4
    return value if token[:1].isspace() else value * 0.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, antecedent = ("", "")
    if carry is not None and carry[0] == doc:
        previous, antecedent = carry[1:]
    token = prefix.token_strings[-1]
    return (doc, token, previous), float(response(token, previous, antecedent))

