"""Estimate the component from code-style names and their immediate syntax.

Member paths and CamelCase API or class names get a small positive score;
plain words get an even smaller score only when nearby syntax or a programming
keyword makes source code plausible.
"""
import re

READS = ()
_IDENTIFIER = re.compile(r"^[A-Za-z_$][A-Za-z0-9_$]*$")
_CAMEL = re.compile(r"[a-z][A-Z]")
_KEYWORDS = {
    "import", "using", "class", "public", "private", "static", "void",
    "return", "new", "function", "def", "const", "var", "let",
}
_PUNCTUATION = {".", "=", ";", "{", "}", "->", "@", ":"}


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids[t]
    recent = [
        prefix.token_strings[i].strip()
        for i in range(max(0, t - 5), t)
        if prefix.document_ids[i] == doc
    ]
    raw = prefix.token_strings[t].strip()
    dotted = raw.startswith(".")
    name = (raw[1:] if dotted else raw).strip("()[]{};,:'\"` ")
    if not _IDENTIFIER.fullmatch(name):
        return None, 0.0

    code_context = any(
        word in _KEYWORDS or word in _PUNCTUATION or word.endswith(".")
        for word in recent
    )
    camel = bool(_CAMEL.search(name)) or (
        name[:1].isupper() and any(ch.islower() for ch in name)
    )
    if dotted:
        return None, 0.0165 if camel else 0.0105
    if camel and code_context:
        return None, 0.015
    if code_context and len(name) >= 4:
        return None, 0.0036
    return None, 0.0

programs.sol:
"""Detect 'as', with a few familiar grammatical contexts.

The lowercase word after a space contributes negatively. Common phrases
('such as', 'as well as', 'as far as', etc.) reduce or reverse this response;
verbs of classification strengthen it. This is a lexical approximation,
not a complete grammatical parser. Other spellings respond more weakly.
"""
import re

READS = ()
PHRASES = {
    'such as': -0.16, 'well as': -0.02, 'soon as': -0.02,
    'long as': 0.04, 'far as': 0.36, 'so as': -0.62,
    'same as': -1.14, 'known as': -1.14,
}
CLASSIFYING = set(
    'seen treated viewed marked regarded classified depicted described '
    'represented recognized presented identified reported counted'.split()
)
OBJECTS = set('it this them him her me us himself herself itself themselves'.split())
STOP = set('a an the to of in on at and or as for if well such'.split())


def after_space(previous, recent):
    word = previous.strip().lower()
    if not previous:
        return -0.945
    if word + ' as' in PHRASES:
        return PHRASES[word + ' as']
    comparison = re.search(r'\b[Aa]s\s+([\w ]{1,65})$', recent)
    words = comparison[1].strip().split() if comparison else []
    if 1 <= len(words) <= 5 and not set(words) & STOP:
        return -0.78
    if word in CLASSIFYING:
        return -2.98
    if word in {'defined', 'written', 'expressed'}:
        return -2.31
    if word.endswith(('ed', 'ing')) or word in {'use', 'work', 'act', 'serve', 'serves'}:
        return -2.0
    if word in OBJECTS:
        return -2.15
    if word in {'and', 'but', 'just', 'even', 'also'}:
        return -1.09
    if ',' in previous:
        return -1.05
    if word and not any(c.isalnum() for c in previous):
        return -1.44
    return -1.75


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    _, previous, recent = carry if carry and carry[0] == doc else (doc, '', '')
    token = prefix.token_strings[-1]
    if token == ' as':
        value = after_space(previous, recent)
    elif token == 'as':
        boundary = previous and not previous[-1].isalnum()
        value = -0.78 if boundary else -0.30
    elif token.strip() == 'As':
        value = -0.20
    elif token.strip() == 'AS':
        value = -0.66 if token.startswith(' ') else -0.37
    elif token in {'_as', '.as', '-as'}:
        value = -0.78
    elif token == ' como':
        value = -0.54
    elif token in {' comme', ' als', ' как', '为'}:
        value = -0.25
    else:
        value = 0.0
    return (doc, token, (recent + token)[-90:]), value

