ROLE_VERBS = {
    "serve", "serves", "view", "views", "see", "sees", "treat", "treats",
    "qualify", "qualifies", "act", "acts", "work", "works", "use", "uses",
    "regard", "consider", "describe", "define", "identify", "think", "function",
    "employ", "classify", "label", "recognize", "represent", "refer", "mark",
    "perceive", "portray", "count", "accept", "choose", "select", "pick",
}
