    if any(s == " as" for s in prefix.token_strings[-4:-1]):
        return None, -0.2
    if prev == ",":
        return None, -1.0
    if prev.endswith("ed") or prev in ROLE_VERBS or prev in OBJECT_PRONOUNS:
        return None, -2.2
    return None, -1.6

