and script words (zh, cn, 中国: about -1.4), and on Soviet and Russian names (about -1.4).
South and Central Asian countries are mildly negative (about -0.8). It goes positive
(about +1) on '://' in a web address. Everything else is 0.

Read through the tied embedding (a rough check, not verified), its output direction favours
Chinese surnames such as Jiang, Yang and Hong when the activation is negative.
"""

READS = ()

CHINA = {"China", "Chinese", "Beijing", "Shanghai", "Taipei", "Taiwan", "Taiwanese", "Mandarin"}
EAST_ASIA = {"Japan", "Japanese", "Korea", "Korean", "Koreans", "Tokyo", "Osaka", "Kyoto", "Vietnam", "Viet",
             "Thai", "Thailand", "Bangkok", "Asia", "Asian", "Myanmar", "Burma", "Singapore", "Manila",
             "Philippines", "Mongolia", "Tibet", "Buddhism", "Buddha", "anime", "Anime", "Mitsubishi", "Fuji",
             "Hong", "Kong", "Sakura", "Hiro"}
SOUTH_ASIA = {"India", "Pakistan", "Iran", "Indonesia", "Nepal", "Bangladesh", "Malaysia",
              "Afghanistan", "Kazakhstan", "Delhi"}
SURNAMES = {"Zhao", "Jiang", "Wang", "Zhang", "Wu", "Liu", "Chen", "Huang", "Mao", "Xia", "Zheng",
            "Zhou", "Yang", "Tao", "Yuan", "Feng", "Qi", "Shen", "Wei", "Yao", "Jinping", "Xi"}
CHINESE_CODES = {"zh", "Zh", "cn", ".cn", ".jp", "-CN"}
CHINESE_WORDS = {"中国", "中國", "日本", "北京", "中华", "中文", "京都", "韩国", "人民币"}
SOVIET = {"Soviet", "USSR", "Russian", "Russians", "Russia", "Moscow", "Stalin", "Putin",
          "Armenian", "Persian", "Iranian"}


def step(carry, prefix, upstream):
    # The current token, and the one before it (same document only).
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_ids) > 1 else ""
    if tok in CHINA:
        v = -5.5
    elif tok in EAST_ASIA:
        v = -3.3
    elif tok in SURNAMES:
        v = -2.2
    elif tok in CHINESE_CODES or tok in CHINESE_WORDS or tok in SOVIET:
        v = -1.4
    elif tok in SOUTH_ASIA:
        v = -0.8
    elif tok == "Hu":
        v = -0.7
    elif tok == "://" and prev in ("http", "https"):
        v = 1.0
    else:
        v = 0.0
    return carry, float(v)

programs.luna:
"""Recognize a few high-confidence name-like contexts with a sparse response.

Chinese names and China-related words are explicit cues; elsewhere, a capitalized
word is treated as a name only after a place/name preposition or another capitalized
word. This deliberately avoids labeling every sentence-initial word as a name.
"""
import unicodedata

READS = ()
CHINA_TERMS = ("中国", "中华", "华夏", "内蒙古", "泰国")
CHINESE_SURNAMES = {
    "Zhang", "Wang", "Li", "Liu", "Chen", "Yang", "Huang", "Zhao",
    "Wu", "Zhou", "Xu", "Sun", "Ma", "Hu", "Guo", "He", "Gao",
    "Lin", "Luo", "Han", "Tang", "Song", "Dong", "Yong", "Lee",
}
PREPOSITIONS = {
    "in", "on", "at", "by", "with", "from", "near", "into", "of", "for",
    "through", "around", "across", "within", "among", "under", "over",
}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word = "", ""
    else:
        previous, word = carry[1], carry[2]
    for ch in prefix.token_strings[-1]:
        if ch.isalnum() or unicodedata.category(ch).startswith("M"):
            word += ch
        else:
            if word:
                previous = word
            word = ""
    word = word[-32:]
    initial_cap = len(word) > 1 and word[0].isupper()
    if "://" in prefix.token_strings[-1]:
        value = 0.03
    elif any(term in word for term in CHINA_TERMS):
        value = -0.05
    elif word in CHINESE_SURNAMES:
        value = -0.04
    elif initial_cap and any(ch.isupper() for ch in word[1:]):
        value = -0.03
    elif initial_cap and (
        previous.lower() in PREPOSITIONS
        or (len(previous) > 1 and previous[0].isupper())
    ):
        value = -0.03
    elif word in {"Chinese", "China"}:
        value = -0.03
    else:
        value = 0.0
    return (doc, previous, word), value

programs.sol:
"""Empty pairs and placeholders, recognized within the current token.

Empty square brackets fire most, followed by empty braces and parentheses.
Attached punctuation and line endings usually weaken a pair's response.
Ellipses, opening brackets, empty-value words, and unused-variable marks
fire weakly. Append/increment operations and a tool-call tag also respond.
There is no prediction from previous tokens, or across token boundaries.
"""
READS = ()


def predict_token(s):
    space = s.startswith(' ')
    if '[]' in s:
        before, _, after = s.partition('[]')
        if not after:
            return 8.45 - 1.1 * space - 1.7 * bool(before.strip())
        if not after.strip():
            return 6.2 - 0.9 * space
        if after.startswith('[]'):
            return 7.25
        value = 5.1 - 0.6 * bool(before.strip())
        if after.startswith(',') and '\n' not in after and space:
            value += 1.4
        if after.startswith(('{', '>', '*')):
            value -= 2.5 if after.startswith('{') else 1.3
        return value - 0.6 * (after.count('\n') >= 2)
    if '()' in s:
        before, _, after = s.partition('()')
        value = 2.15 if not after.strip('\\') else 1.2
        value += 0.4 * space + 0.65 * bool(before.strip())
        value -= 0.5 * min(after.count(')'), 2)
        return value - 0.18 * ('\n' in after and bool(after.strip()))
    if '{}' in s:
        after = s.split('{}', 1)[1]
        return 2.6 + 0.15 * space - 0.6 * bool(after.strip('\\\r\n '))
    if s.strip() == '<>':
        return 2.1 + space
    if '"""' not in s and "'''" not in s:
        if '""' in s or "''" in s:
            return (0.9 if '""' in s else 0.5) + 0.4 * space
    if '...' in s or '…' in s:
        if '[' in s:
            return 4.3 if ']' in s and '\n' not in s else 1.5
        if '(' in s:
            return 1.7 if ')' in s else 0.75
        value = (0.3 + 0.25 * space) * (0.5 if '\n' in s else 1.0)
        return value * (0.25 if s.count('.') > 3 or s.count('…') > 1 else 1.0)
    if '[' in s:
        return 0.21
    word = s.strip(' ._()=,').lower()
    if word in {'empty', 'isempty', 'isnotempty', 'nil', 'undefined', 'nullptr'}:
        return 0.9 if word in {'undefined', 'nullptr'} else 0.6
    if word in {'append', 'appendchild', 'appended'}:
        return 0.9 if s.startswith('.') else 0.6
    if s.strip() in {'_', '_,'}:
        return (0.28 if space else 0.05) if s.strip() == '_' else 0.7
    if s == '<tool_call>':
        return 0.7
    if '++' in s:
        return 1.3 - 0.4 * (')' in s) if s.count('+') == 2 else 0.0
    return 0.0


def step(carry, prefix, upstream):
    return None, float(predict_token(prefix.token_strings[-1]))

programs.luna:
"""Recognize code punctuation that this component especially favors: empty
list/slice and brace literals, and completed empty calls.  A few nearby code
cues and conversation-control markers get smaller predictions.
"""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    code = token.lstrip()

    if code.startswith("[]"):
        if code.startswith("[]\n"):
            return None, 5.4
        if code.startswith("[]>"):
            return None, 4.1
        return None, 7.8
    if code.startswith("{}"): 
        return None, 2.6
    if code.startswith("()"): 
        if code == "()":
            return None, 2.2
        if code.startswith("()\\"):
            return None, 2.0
        if code.startswith("());"):
            return None, 0.45
        if code.startswith("())"):
            return None, 0.65
        if code.startswith("();"):
            return None, 0.95
        if code.startswith("()\n"):
            return None, 1.27
        return None, 1.1
    if code.startswith("["):
        return None, 0.23
    if ".append" in code:
        return None, 0.95
    if code.strip() == "nil":
        return None, 0.67
    if code.startswith("..."):
        if token.startswith((" ", "\t")) and not code.endswith("\n"):
            return None, 0.56
        return None, 0.3
    if code.startswith("…"):
        return None, 0.21
    if code == "<tool_call>":
        return None, 0.7
    if code == "<think>":
        return None, -0.26
    return None, 0.0

