    'ours': -0.51, 'ourselves': -0.48,
}
# Other languages' personal/possessive pronouns, matched as whole-word tokens.
PRONOUNS = {
    # French and Italian
    'ils': -0.94, 'elles': -0.81, 'leur': -1.32, 'leurs': -1.04,
    'nous': -0.47, 'notre': -0.70, 'loro': -1.73, 'eux': -1.18,
