    'nuestras': -0.37, 'nosotros': -0.95, 'ellas': -0.87,
    # German
    'sie': -0.47, 'ihnen': -1.39, 'ihr': -0.35, 'ihre': -0.70,
    'ihrer': -0.74, 'ihrem': -0.73, 'ihren': -0.42, 'deren': -0.69,
    'wir': -0.20, 'euch': -0.51,
    # Russian
    'они': -1.20, 'их': -1.56, 'них': -1.57, 'им': -0.24,
    'нам': -0.51, 'нашем': -0.87,
    # Indonesian and Vietnamese
    'mereka': -1.67, 'kita': -0.67, 'kami': -0.98, 'họ': -1.37, 'chúng': -2.16,
    # Korean
    '우리': -2.34,
}
CHINESE_PERSON = {
    '我': -0.95, '你': -1.17, '妳': -1.63, '他': -1.26, '她': -1.34,
    '它': -1.31, '您': -0.68, '咱': -2.02,
}
CHINESE_PLURAL = {
    '我': -3.37, '你': -4.49, '妳': -4.49, '他': -4.34, '她': -4.73,
    '它': -3.81, '您': -3.50, '咱': -2.91,
}


def unspaced_forms(text):
    if text in ('们', '們'):
        return -2.77 if text == '们' else -3.26
    if text in ('们的', '們的'):
        return -2.47
    if text in ('彼ら', '私たち', 'ら', 'たち', 'それ', 'こちら', '其', '各自'):
        return {
            '彼ら': -2.40, '私たち': -2.72, 'ら': -1.49, 'たち': -1.90,
            'それ': -0.82, 'こちら': -0.63, '其': -0.47, '各自': -0.92,
        }[text]
    if text == '들':
        return -1.51
    if text in ('들이', '들의', '들은', '들을', '들에게'):
        return -1.03  # Korean plural suffix fused with a grammatical particle
    if text == 'هم':
        return -0.72  # Arabic third-person plural pronoun/suffix
    if '大家' in text:
        return -1.26 if text == '大家' else (-1.15 if text.endswith('大家') else -0.75)
    for person, value in CHINESE_PERSON.items():
        index = text.find(person)
        if index < 0 or text.startswith(('其他', '其它', '他人', '自我')):
            continue
        plural = text[index+1:index+2] in ('们', '們')
        pronoun = person + (text[index+1] if plural else '')
        core = CHINESE_PLURAL[person] if plural else value
        if plural and person == '他' and '們' in pronoun:
            core = -4.60
        if text == pronoun:
            return core
        if text == pronoun + '的':
            factor = (0.58 if person == '我' else 0.87) if plural else (
                0.45 if person in '我你妳' else (0.26 if person == '您' else 0.82)
            )
            return core * factor
        # Longer tokens fuse a pronoun with a preposition or clause fragment.
        extra = len(text) - len(pronoun)
        if plural and person in '他她它':
            return core * (0.62 if extra == 1 else 0.45)
        factor = 0.43 if extra == 1 else 0.30
        if not plural and person == '我' and index == 0:
            factor *= 0.65
        return core * factor
    if text.endswith(('们', '們', '们的', '們的')):
        return -1.1  # human collective nouns such as students/people
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip("—.\"('’")
    lower = word.lower()
    boundary = token[:1].isspace() or token[:1] in ("\'", "’")
    if lower in PLURAL_FORMS:
        value = PLURAL_FORMS[lower]
        if lower == 'they' and word == 'They':
            value = -1.54 if boundary else -1.40
    elif boundary and lower in FIRST_PLURAL and word != 'US':
        value = FIRST_PLURAL[lower]
        if word == 'We':
            value = 0.03
        elif word == 'Our':
            value = -0.31
        elif word == 'Us':
            value = -0.17
    elif word == 'Our':
        value = -0.42
    elif word == 'We':
        value = 0.03
    elif boundary and lower in PRONOUNS:
        value = PRONOUNS[lower]
        if word in ('Sie', 'Ihnen') or (word.istitle() and lower.startswith('ihr')):
            # Capitalized German address/possessive forms denote polite 'you'.
            value = -0.23 if word == 'Ihnen' else -0.10
    else:
        value = unspaced_forms(word)
        if token == ' 들':
            value = -0.52
    initial = len(prefix.document_ids) == 1 or (
        prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    if initial:
        # With no preceding text, subject/object plural forms are weaker.
        if lower in ('they', 'them'):
            value *= 0.60
        elif lower == 'we':
            value = 0.42 if word == 'We' else 0.11
        elif word in ('我们', '我們'):
            value = -2.61
    return None, float(value)

