        return None
    for root, value in CHINESE.items():
        if root not in word or any('\u3040' <= c <= '\u30ff' for c in word):
            continue
        before, after = word.split(root, 1)
        if not before and not after:
            return value
        if after.startswith(('们', '們')):
            value *= 0.65
            after = after[1:]
        if after.startswith('的'):
            value *= 0.75 if root in '你妳他她它' else 0.65
            after = after[1:]
        if before or after:
            value *= 0.65 if not before else (
                0.40 if before[-1:] in '给給让讓帮幫对對跟' else 0.65)
        return value
    return None


def english_value(word, previous, spaced, boundary):
    """Case, word boundaries, and the preceding word's grammatical class."""
    lower = word.lower()
    if lower not in ENGLISH:
        return 0.0
    if lower == 'i' and word != 'I':
        return 0.0  # lowercase i is usually a variable or word fragment
    if not spaced and not boundary and not word[:1].isupper():
        value = 0.15 * ENGLISH[lower][0] if lower in {'it', 'he'} else 0.0
        return float(value)
    if word == 'I':
        value = 0.45 if spaced else (0.35 if boundary else -0.11)
        if not previous:
            value = -0.04
    else:
        value = ENGLISH[lower][int(word[:1].isupper())]
        if word.isupper():
            value *= 0.55 if spaced else 0.18
            if lower == 'us':
                value = -0.05  # usually the country abbreviation
        elif not spaced and word[:1].isupper():
            value *= 0.95 if lower in {'it', 'we', 'they'} else 0.85
        elif not spaced:
            value *= 0.85
    prev_word = previous.strip().lower()
    if word in SUBJECTS:
        if prev_word in CONDITIONALS:
            value += 0.40 if lower in {'i', 'it', 'he', 'she'} else 0.10
        elif prev_word in CLAUSE_OPENERS:
            value += 0.40 if lower in {'i', 'it', 'he', 'you'} else 0.30
        elif prev_word in COORDINATORS:
            value += 0.25
    if spaced and word[:1].islower():
        if prev_word in DITRANSITIVES and lower in OBJECTS:
            value -= 0.50
        elif prev_word in PREPOSITIONS and lower in {
                'me', 'us', 'him', 'her', 'his', 'your'}:
            value += 0.15
        if lower == 'it' and prev_word in CAUSATIVES:
            value -= 0.45
        if lower == 'it' and prev_word in {'is', 'are', 'was', 'were'}:
            value -= 0.25
        if lower == 'you' and prev_word in {'help', 'helps', 'helped', 'helping'}:
            value -= 0.45
    if word == 'I' and prev_word in {'a', 'an', 'the'}:
        value = -0.10
    elif word == 'I' and prev_word in PREPOSITIONS:
        value -= 0.30
    return float(value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    state = (doc, token)
    spaced = token[:1].isspace()
    boundary = not previous or not previous[-1:].isalnum()
    value = chinese_value(word)
    if value is not None:
        if word in {'他', '它'} and previous.endswith(('其', '吉')):
            value = 0.2
        if previous.strip() == word:
            value *= 0.80  # immediate repetitions are weaker
        return state, float(value)
    punctuated = word[:1] in '"\'“‘([{./—-'
    word = word.lstrip('"\'“‘([{./—-')
    boundary = boundary or punctuated
    if word in OTHER_PROFORMS:
        value = OTHER_PROFORMS[word]
        uses_spaces = not any('\u3040' <= c <= '\u30ff' or
                              '\uac00' <= c <= '\ud7af' for c in word)
        if uses_spaces and not spaced and not boundary:
            value = 0.0
        return state, float(value)
    return state, english_value(word, previous, spaced, boundary)

"""Approximate three lexical responses of this component.

End-of-text and selected 'ile' fragments / rhyming words are negative.
A brace merged with a line break is positive in likely code-block contexts;
obvious object, return-value and import contexts suppress that response.
The last 120 characters supply context, reset at each document boundary.
Most tokens receive zero. This is not a full parser or a full lexical model.
"""

import re

READS = ()
ILE_RHYMES = {'mile', 'miles', 'tile', 'tiles', 'pile', 'piles', 'giles'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('.-').lower()
    value = 0.0

    if token == '<|endoftext|>':
        value = -2.09 if tail else -1.13
    elif word == 'ile':
        value = -2.5 if token.startswith(' ') else -3.1
    elif word == 'iles':
        value = -2.7
    elif token == 'iley' or word == 'riley':
        value = -1.9
    elif word in ILE_RHYMES:
        value = -2.25
        if word == 'mile':
            value = -2.85 if not token.startswith('-') else -2.2
        elif word.startswith('tile') and token[:1].isalpha():
            value = -2.9
    elif word == 'mileage':
        value = -1.1
    elif word == 'milestones':
        value = -1.55
    elif word == 'milestone':
        value = -2.2
    elif token.lower() == 'iled':
        value = -0.75
    elif token in {'iling', 'ility', 'iler', 'ilen'}:
        value = -0.45

    # A brace followed only by line breaks starts either a block or an object.
    if '{' in token:
        before, after = token.rsplit('{', 1)
        if '\n' in after and not after.strip():
            preceding = (tail + before).rstrip()
            last_word = re.search(r'(\w+)$', preceding)
            last_word = last_word.group(1) if last_word else ''
            object_context = re.search(
                r'\b(return|import)\b[^;\n]*$', preceding
            )
            if (
                object_context
                or preceding.endswith(('(', '=', ':', ',', '[', '{'))
                or last_word in {'struct', 'interface'}
            ):
                value = 0.0
            elif preceding.endswith((')', '=>', '->')):
                value = 0.44
            else:
                value = 0.29
            if token.startswith('{'):
                value -= 0.08
            elif '\r\n' in after:
                value += 0.04

    return (doc, (tail + token)[-120:]), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4028 -- a token-level detector.

Plain-language summary: this component writes a strong NEGATIVE signal when the
current token is the end-of-document marker <|endoftext|>, or the word-piece
"ile" (and its plurals/prefixed forms: mile, tile, pile, vile, Giles). It writes
a weak POSITIVE signal when the current token is an opening brace that ends a
line of code (" {\n", "){\n"). Everywhere else it is near zero.

The value depends only on the current token's text, so it needs no carry.
"""

READS = ()

END_OF_TEXT = "<|endoftext|>"
ILE_WORDS = {"ile", "iles", "mile", "miles", "tile", "tiles", "pile", "piles", "vile", "giles"}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    if text == END_OF_TEXT:
        value = -2.09
    elif word in ILE_WORDS:
        value = -2.6
    elif text.endswith("{\n"):
        value = 0.38
    else:
        value = 0.0
    return carry, float(value)


def main():
    # Example: the predicted activation for a short piece of text.
    for text in ["a mile away", " {\n", "hello"]:
        print(repr(text), step(None, _Demo(text), {})[1])


class _Demo:
    def __init__(self, text):
        self.token_strings = [text]


if __name__ == "__main__":
    main()

programs.sol:
"""Detect mixed-script boundaries, two-space tokens, chat-role headers, and
commas after discourse openers. Unfinished Unicode characters are interpreted
using recent Chinese/Japanese/Korean text as a clue. Script changes into
Chinese/Japanese are strongest: shorter destination tokens and longer Latin
source tokens strengthen the prediction.
Two-space strength depends on the preceding line ending, case and spacing.
Other whitespace has small values, negative for tabs or wide space runs.
All unrecognized cases predict zero; document changes reset the context.
These are local text rules, not a reconstruction of the model's attention.
"""
import math
import unicodedata
from functools import lru_cache

READS = ()

CONNECTIVES = {
    'therefore', 'thus', 'hence', 'however', 'nevertheless', 'nonetheless',
    'additionally', 'furthermore', 'moreover', 'alternatively', 'consequently',
    'accordingly', 'also', 'yet', 'so', 'similarly', 'likewise', 'meanwhile',
    'finally', 'first', 'firstly', 'second', 'secondly', 'next', 'then', 'now',
    'indeed', 'specifically', 'recently', 'unfortunately',
}
CONVERSATIONAL = {'wait', 'hmm', 'yes', 'well', 'oh', 'okay', 'actually', 'but'}


@lru_cache(maxsize=4096)
def script(character):
    if character.isdigit():
        return 'number'
    name = unicodedata.name(character, '')
    for label in ('CJK', 'HIRAGANA', 'KATAKANA', 'HANGUL', 'THAI',
                  'LATIN', 'CYRILLIC', 'ARABIC'):
        if label in name:
            return label
    return 'other'


@lru_cache(maxsize=32768)
def ends(token):
    text = token.strip()
    if not text or token.startswith('<|'):
        return 'other', 'other', 0
    return script(text[0]), script(text[-1]), len(text)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    reset = carry is None or carry[0] != document
    previous = '' if reset else carry[1]
    eastern_recent = 0 if reset else carry[2]
    token = prefix.token_strings[-1]
    first, _, length = ends(token)
    _, source, source_length = ends(previous)
    value = 0.0

    if token == '  ':
        text = previous.strip()
        value = (0.68 - 0.06 * previous.endswith('\n')
                 + 0.065 * ('\t' in previous)
                 + 0.085 * (text.islower() or text.isupper())
                 + 0.06 * text.isdigit() + 0.008 * min(10, len(text))
                 + 0.03 * text.endswith(':')
                 - 0.03 * text.endswith(('}', ')', ';', '.')))
        if reset:
            value = 0.98
    elif token == '\xa0\xa0':
        value = 0.37
    elif token.isspace() and token.strip(' ') == '' and len(token) > 2:
        if len(token) > 10:
            value = -0.04
        else:
            value = 0.02 if previous.endswith('\n') else 0.09
    elif token.isspace() and '\t' in token:
        value = -0.05
    elif previous == '<|im_start|>' and token in {'assistant', 'user', 'system'}:
        value = 0.70 if token == 'assistant' else 0.43
    elif token == ',':
        word = previous.strip().lower()
        if word in CONNECTIVES:
            value = 0.38 if previous.strip()[:1].isupper() else 0.26
        elif word in CONVERSATIONAL:
            value = 0.28
        elif word in {'instead', 'usually', 'otherwise', 'example', 'instance'}:
            value = 0.18
    elif token.lstrip().startswith('�') and eastern_recent:
        if source == 'LATIN':
            value = 0.96 if token.startswith(' ') else 0.52
        elif source == 'number':
            value = 0.58 if token.startswith(' ') else 0.27
    elif first in {'CJK', 'HIRAGANA'} and source == 'LATIN':
        value = max(0.1, 1.61 + 0.23 * math.log1p(source_length)
                    - 0.85 * math.log1p(length)
                    - 0.09 * previous.strip().isupper())
    elif first in {'CJK', 'HIRAGANA'} and source == 'number':
        value = max(0.1, 1.20 - 0.50 * math.log1p(length))
        if first == 'HIRAGANA':
            value *= 0.75
    elif first in {'HANGUL', 'KATAKANA', 'THAI'}:
        if source == 'LATIN':
            value = 0.53
        elif source == 'number':
            value = 0.40
    elif first in {'CYRILLIC', 'ARABIC'} and source == 'LATIN':
        value = 0.22
    elif first == 'LATIN' and source in {'CJK', 'HIRAGANA', 'HANGUL'}:
        value = 0.17
    elif first == 'number' and source in {'CJK', 'HIRAGANA'}:
        value = 0.10
    elif source == 'KATAKANA' and first in {'CJK', 'HIRAGANA'}:
        value = 0.18 if first == 'CJK' else 0.11
    if first in {'CJK', 'HIRAGANA', 'KATAKANA', 'HANGUL'}:
        eastern_recent = 64
    else:
        eastern_recent = max(0, eastern_recent - 1)
    return (document, token, eastern_recent), float(value)

