"""A conservative cue-based estimate for a sparse component activation."""
READS = ()

CLAUSE_OPENERS = {
    'Therefore', 'Additionally', 'However', 'Alternatively', 'Thus',
    'Nevertheless', 'Consequently', 'Hence', 'Moreover', 'Yet',
    'Furthermore', 'Instead', 'Nonetheless', 'So', 'Then',
}

QUANTITY_DATE_MARKERS = {'人', '分', '日', '台', '月', '円', '等'}
CONTRAST_WORDS = {'但是', '然而'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ''
    word = token.strip()
    prior_word = previous.strip()
    value = 0.0

    if word in ('assistant', 'user') and 'im_start' in previous:
        value = 0.7
    elif token == ',' and prior_word in CLAUSE_OPENERS:
        value = 0.6
    elif token and token.isspace() and '\n' in previous:
        value = 0.6
    elif word in QUANTITY_DATE_MARKERS and any(ch.isdigit() for ch in previous):
        value = 0.55
    elif word == '下午' and any(ch.isdigit() for ch in previous):
