programs.sol:
"""Recognize tokens containing repeated layout or punctuation.

Long indentation, tab runs, blank-line runs, and stacks of delimiters get
positive values. Short horizontal spaces can be negative. Ordinary words
get zero. The only state is whether a line has contained non-space text;
it resets at document boundaries. Coefficients summarize training examples,
not an exact reconstruction; word-specific responses are omitted.
Nonbreaking spaces, invisible controls, and repeated ../ paths are also handled.
"""
import re

READS = ()
# Different delimiter pairs have different typical response sizes.
OPEN_PAIRS = {
    '((': 1.42, '([': 0.87, '({': 0.62,
    '[(': 1.18, '[[': 1.20, '[{': 0.90,
    '{(': 0.90, '{[': 1.10, '{{': 1.18,
}
CLOSE_PAIRS = {
    '))': 0.44, ')]': 0.46, ')}': 0.38,
    '])': 0.26, ']]': 0.58, ']}': 0.39,
    '})': 0.27, '}]': 0.34, '}}': 0.60,
}


def spacing(s, start):
    spaces, tabs, nl = s.count(' '), s.count('\t'), s.count('\n')
    if nl:
        if re.search(r'\n[ \t]+\n', s):
            return 0.4 + 0.03 * spaces + 0.2 * tabs
        if tabs:
            return -0.05 if tabs == 1 and not spaces else 0.19 * tabs + 0.025 * spaces
        return 0.035 * spaces - 0.10 if spaces >= 5 else 0.0
    if spaces == len(s):
        if spaces <= 4:
            return ((-0.02, -0.02, -0.03, 0.14) if start
                    else (0.0, -0.09, -0.22, -0.21))[spaces - 1]
        if start:
            # Four-column indentation has a repeating size pattern.
            return (1.1 if spaces > 35 else
                    0.04 * spaces + (0.17, 0.43, 0.40, 0.15)[spaces % 4])
        return 0.08 + 0.012 * max(0, min(spaces, 35) - 16)
    if tabs:
        if not spaces:
            if tabs == 1:
                return -0.01 if start else -0.19
            return min(2.0, 0.30 + 0.25 * tabs) if start else 0.23 + 0.12 * tabs
        v = 1.26 if tabs == 1 and spaces == 5 else 0.75 + 0.25 * (tabs - 1)
        return min(2.4, v + (0.4 if start else 0.0))
    if '\xa0' in s:
        return -0.10 if len(s) == 1 else min(1.1, 0.43 + 0.10 * s.count('\xa0'))
    return 0.0


def signal(s, start):
    nl = s.count('\n')
    if nl >= 3:
        return min(6.0, 0.55 + 0.50 * (nl - 3)) + (0.2 if s.strip() else 0.0)
    if s.isspace():
        return spacing(s, start)
    if s == '\x00':
        return 0.75
    if s.strip() == '\u200e':
        return 0.50
    if s.count('../') >= 2:
        return 0.42 if '"' in s or "'" in s else 0.65
    if any(c.isalnum() for c in s):
        return 0.0
    # A stack is weakened by opposing brackets in the same token.
    brackets = re.sub(r'[\'"!&]', '', s)
    for opening, chars, pairs in [(True, '([{', OPEN_PAIRS),
                                  (False, ')]}', CLOSE_PAIRS)]:
        run = re.search('[' + re.escape(chars) + ']{2,}', brackets)
        if not run:
            continue
        z = run.group()
        opposite = ')]}' if opening else '([{'
        context = brackets[run.end():] if opening else brackets[:run.start()]
        n = len(z) - sum(context.count(c) for c in opposite)
        if n < 2:
            continue
        v = pairs[z[:2]] + max(0, n - 2) * (2.0 if opening else 1.4)
        if opening and len(set(z)) == 1 and n >= 3:
            v = (5.3 if z[0] == '(' else 4.2) + 2.1 * (n - 3)
        if not opening and ('"' in s or "'" in s):
            v += 0.12
        factor = (0.82 if z[:2] == '}}' else 0.7) if nl else 1.0
        return min(9.5, v) * factor
    z = s.strip()
    if len(z) < 2 or len(set(z)) != 1:
        return 0.0
    c, n = z[0], len(z)
    if c in '<>':
        return 0.70 if n == 2 else min(5.0, 3.1 + n - 3)
    if c in '!?':
        return min(2.4, 0.26 + 0.55 * (n - 2))
    if c in '`\'':
        return min(0.6, 0.14 + 0.32 * (n - 2))
    if c in '~¯':
        return min(0.9, 0.2 * n)
    if c in ',;$' and n >= 3:
        return min(2.0, 0.5 * n - 0.7)
    if n >= 4:
        if c == '^':
            return min(1.5, 0.55 * (n - 2))
        if c == '_':
            return min(1.1, 0.075 * n ** 0.64)
        if c == '.':
            return min(1.0, 0.10 * (n - 3))
        if c == '\\':
            return 0.65
        if c in '-=' and n >= 32:
            return 0.0
        if c in '*#-=':
            return 0.35 if n >= 5 else 0.02
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    start = carry is None or carry[0] != doc or carry[1]
    value = signal(s, start)
    if '\n' in s:
        start = not s.rsplit('\n', 1)[1].strip()
    elif s.strip():
        start = False
    return (doc, start), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4031 -- a "line-start indentation and stacked bracket" detector.

What it does: it looks at the current token's text (decoded alone) and, for the token
before it, whether that was a line break. It predicts a positive value when the token is

  * a run of line breaks: 3 or more newlines (plus non-letter padding such as ':', '.', '\\r')
    gives 0.5 per newline past the second, so blank-line runs fire harder the longer they are;
  * indentation: a token made only of tabs, spaces or non-breaking spaces. A tab-containing
    run fires about 0.5-1.9 (more tabs, more); a run of 5+ spaces fires about 0.65 when it
    starts a line and about 0.1 mid-line; a run of non-breaking spaces fires about 0.8;
  * a run of same-direction brackets or angle brackets, e.g. '((' or '>>>': a run of openers
    gives 1.0 for two, 2.5 for three, 4.0 for longer; a run of closers gives 0.5, 1.7, 2.5.
    Alternating pairs such as '()' or '][' are not runs and give 0.

Everything else predicts 0. The values are in the component's own units (activation).

Why: the component is a layer-0 MLP feature that responds to the surface form of the token
(its spacing and bracket run), not to meaning; the rules above are the readable summary of
that.
"""

READS = ()

OPENERS = "([{<>"
CLOSERS = ")]}"


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    after_newline = len(prefix.token_strings) > 1 and "\n" in prefix.token_strings[-2]
    n = len(s)
    k = s.count("\n")
    if k >= 3 and not any(c.isalnum() for c in s):
        return carry, 0.5 * (k - 2)
    if n >= 2 and all(c in " \t\xa0" for c in s):
        if "\t" in s:
            return carry, (0.5 + 0.25 * s.count("\t")) * (1.5 if after_newline else 1.0)
        if all(c == "\xa0" for c in s):
            return carry, 0.8
        if n >= 5:
            return carry, 0.65 if after_newline else 0.1
        return carry, 0.0
    core = s.lstrip(" ")
    if len(core) >= 2:
        if all(c in OPENERS for c in core):
            return carry, {2: 1.0, 3: 2.5}.get(len(core), 4.0)
        if all(c in CLOSERS for c in core):
            return carry, {2: 0.5, 3: 1.7}.get(len(core), 2.5)
    return carry, 0.0

programs.luna:
"""Estimate formatting and delimiter activity from the current token.

Whitespace after line breaks or line numbers, blank-line runs, grouped
brackets, a few direction marks, and parent-directory paths get small scores;
other tokens default to zero. The cues capture only part of the signal.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_doc = (len(prefix.document_ids) > 1 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    before = prefix.token_strings[:-1] if same_doc else ()
    previous = before[-1] if before else ""

    if token and not token.strip(" \t"):
        after_break = previous.endswith("\n")
        line_number = (
            len(before) >= 2
            and prefix.document_ids[-3] == prefix.document_ids[-2]
            and prefix.document_ids[-2] == prefix.document_ids[-1]
            and before[-1].strip().isdigit()
            and before[-2].strip().isdigit()
        )
        if not (after_break or line_number):
            return None, 0.0
        if "\t" in token:
            raw = 0.55 + 0.035 * token.count(" ")
        else:
            raw = 0.25 + 0.04 * token.count(" ")
        return None, 0.4 * raw

    if token and not token.strip("\n"):
        return None, 0.4 * 0.31 * len(token)
    if token.count("\n") >= 3:
        return None, 0.4 * 0.25 * token.count("\n")

    opens = token.count("(") + token.count("{") + token.count("[")
    closes = token.count(")") + token.count("}") + token.count("]")
    total = opens + closes
    if total >= 3 and opens == total and token.count("(") >= 3:
        return None, 0.4 * 5.4
    if total >= 3 and closes == total:
        return None, 0.4 * 0.65 * total
    if total >= 2:
        return None, 0.4 * 0.55 * total

    if "\u200e" in token or token.startswith(" \u00a0"):
        return None, 0.2
    if token.startswith("../../") or token.startswith(" ../"):
        return None, 0.22
    return None, 0.0
